return {
	[20210101] = {
		dec = "<p>&nbsp;&nbsp;魂器学院非常“知名”的特别战术班，在班长到来之前，由千竹、伊文捷琳、莱拉以及伊卡洛维四名学员组成。</p><br/><p>&nbsp;&nbsp;这里的“知名”，并不是完全的褒义词。事实上，大家认识到这个特别战术班，往往是因为一些离奇的事件。</p><br/><p>&nbsp;&nbsp;比如：学院食堂厨房里的食材被糟蹋一通、某学员见义勇为把平民揍成重伤、宿舍的走廊里发现世界级珍惜动物“熊猫”……</p><br/><p>&nbsp;&nbsp;魂器学院一个月大概会发出五条违规通报，每个月都有特别战术班成员的名字在列。</p><br/><p>&nbsp;&nbsp;因此，比起“特别战术班”，大家更喜欢用另一个称呼来指代她们，那就是——“问题小队”。</p><br/><p>&nbsp;&nbsp;除了这些性格上的出格问题之外，小队的成绩单也非常古怪。四位成员的单人作战成绩都非常优秀，然而一到团体测试、情况就急转直下。她们的团体作战不存在任何的战术可言，配合上出现的失误更是数不胜数。这让大家进一步怀疑这个“特别战术班”成立的理由。</p><br/><p>&nbsp;&nbsp;对此，布克丝院长倒是很坦然。“与其让这几位个性突出的问题孩童影响其他学员的队伍，不如让她们自己组建小队，在彼此的身上发现自己的缺陷，没准能取得意外的成长”。</p><br/><p>&nbsp;&nbsp;院长的构想是那么乐观，但这个特别战术班的混乱情况仍是迟迟没有改善——直到“班长”的到来。</p><br/><p>&nbsp;&nbsp;值得一提的是，伊文捷琳是主动请求加入特别战术班的，作为队伍里的“常识人”，她的善良与包容，化解了很多次队伍危机。</p>",
		name = "【特别战术班】",
		story1 = 20210101
	},
	[20210102] = {
		dec = "<p>&nbsp;&nbsp;在拉弥亚执行任务的学员伊文捷琳，最近非常苦恼。</p><br/><p>&nbsp;&nbsp;不知为何，拉弥亚的人们对伊文捷琳的治疗都非常不配合。他们见到伊文捷琳的面貌之后，无论受了多重的伤，都会找着各种各样的理由主动放弃治疗。</p><br/><p>&nbsp;&nbsp;最夸张的一次是，一位拉弥亚当地帮派的小头目，见到伊文捷琳的一瞬间，就扔掉了自己的拐杖，拖着断腿哀嚎着从诊所爬了出去……似乎在他面前的不是伊文捷琳，而是某个可怕的恶魔。</p><br/><p>&nbsp;&nbsp;这不仅让善良的伊文捷琳备受打击，诊所里支援的工作人员也十分困惑。</p><br/><p>&nbsp;&nbsp;无奈，大家只能让伊文捷琳带上口罩执行治疗任务，然而每当患者看清伊文捷琳的眼睛，落荒而逃的情况就再次出现……</p><br/><p>&nbsp;&nbsp;这蹊跷的现象，直到辛西娅的入学才得到解释。</p><br/><p>&nbsp;&nbsp;那位和伊文捷琳一样，拥有一头美丽的珍珠色头发、还有蓝宝石一般眼睛的女孩，是拉弥亚当地最暴力组织的头领。而她的称号——“黑街女王”，在拉弥亚更是死神的代名词。</p><br/><p>&nbsp;&nbsp;原来，银发蓝瞳的不止是天使，也可能是恶魔。</p><br/><p>&nbsp;&nbsp;总之，只能先避免伊文捷琳执行拉弥亚的任务了。</p>",
		name = "【霸道与温情】",
		story1 = 20210102
	},
	[20210103] = {
		dec = "<p>&nbsp;&nbsp;在洛加尔出生的人，对“茶”都有一种特别的情感。他们格外讲究饮茶的礼仪，在别国人们会说“茶会”、“茶艺”，而到了洛加尔，则直接冠以“茶道”之名，显得庄重而肃穆。</p><br/><p>&nbsp;&nbsp;虽然流程有些繁琐，但洛加尔人享受这种感觉。休息日里和朋友们聚集在一起，品上一壶好茶，便是对疲惫身躯的最好馈赠——芙蕾，远坂秋，柳生熏以及风魔胧，这四位学员就是如此。</p><br/><p>&nbsp;&nbsp;起初是芙蕾约远坂秋、柳生熏一起喝茶赏月，等到三人到达学院植物园的天台，发现风魔胧正在此处冥想修行——洛加尔几大传统名门的后代，就这样建立了奇妙的缘分。</p><br/><p>&nbsp;&nbsp;相同的兴趣将她们聚拢到一块，相处之间，四名女孩也逐渐达成了相当的默契。由风魔胧进行侦查，远坂秋与柳生熏进行突破，而芙蕾负责指挥与辅助，如此完备的配置让这只小队愈加成熟，取得了一个又一个优秀的战果。</p><br/><p>&nbsp;&nbsp;如今，若是需要学员去洛加尔执行任务，没有比这四人小队更可靠的选择了。</p>",
		name = "【月下落樱】",
		story1 = 20210103
	},
	[20210104] = {
		dec = "<p>&nbsp;&nbsp;“曼珠沙华”的头领阿加莎，在墨格尔是让人闻风丧胆的名号。</p><br/><p>&nbsp;&nbsp;自幼就通晓弱肉强食的道理，让阿加莎对待敌人毫不留情，甚至会用极不人道的处刑来击溃敌人的心理防线。虽说不是值得称道的做法，然而在墨格尔这块浑噩之地，冷血与铁腕是不可或缺的个性。</p><br/><p>&nbsp;&nbsp;“曼珠沙华”的恐怖还不止于此，传闻说，阿加莎有一只嗜血的“猎犬”，极少有人见过其真容，因为每个“猎犬”的现身之地，都是无人生还的炼狱。</p><br/><p>&nbsp;&nbsp;那就是阿加莎的姐姐，贝蒂。</p><br/><p>&nbsp;&nbsp;虽没有血缘关系，但由同一位父亲养大——那位“曼珠沙华”的前头领，对贝蒂的训练要比阿加莎要严苛得多。</p><br/><p>&nbsp;&nbsp;父亲离世后，贝蒂为辅佐妹妹，从佣兵组织回到墨格尔。在佣兵组织里练就的一身本领，让她成为了比阿加莎还要暴力的战士。但墨格尔几乎无人知晓这个姐姐的存在，于是阿加莎决定利用这个现状，将贝蒂的存在继续隐匿下去——这张强力的底牌，至今还没有失效过。</p>",
		name = "【曼珠沙华 】",
		story1 = 20210104
	},
	[20210105] = {
		dec = "<p>&nbsp;&nbsp;索菲亚可能从来没想过，自己的机器人会被用在“心理疏导”方面。</p><br/><p>&nbsp;&nbsp;艾莉卡与伦茨，两位都是在 人工智能 叛乱中失去双亲的孤儿，“血色情人节”在她们幼小的心灵上留下了无法愈合的伤痕。刚进入学院时，心理老师对她们进行了长时间的心理疏导，但效果十分有限——毕竟 人工智能 叛乱这种“事故”，找遍人类历史都没有第二次。</p><br/><p>&nbsp;&nbsp;尤其是伦茨，出入学院的她对所有人和机械都表现出强烈的抗拒，哪怕是空调那微小的提示音，都会让她恐惧地发出尖叫。这让所有人都感到束手无策。转折发生在一天晚上，索菲亚开发的私人型号机器人·K01 因为程式设定，在伦茨发出尖叫后，停在了她的门前。让大家没想到的是，伦茨对这样一个小巧、且与她头盔有着相似造型的机器人产生了兴趣，她对着小机器人凝视了三分钟，然后对其打了招呼——据悉，那是伦茨进入学院以来第一次主动开口说话。</p><br/><p>&nbsp;&nbsp;然而，那只机器人的发明者索菲亚对此事一无所知，毕竟她制作的机器人数不胜数，放养机器人也是她的乐趣。</p><br/><p>&nbsp;&nbsp;她回想起 K01，那是伦茨带着没电的 K01 站在她房间门口的时候。</p><br/><p>&nbsp;&nbsp;索菲亚会无偿帮助伦茨和艾莉卡，修理她们的机器人伙伴，其实是出于私心——索菲亚对喵球和 K01 里的数据非常感兴趣。但久而久之，让两名女孩也对她产生了依赖。就算不是机器人出了事情，伦茨与艾莉卡也总是第一时间想到索菲亚、寻求她的帮助。例如不会使用网购软件、找不到教室，甚至深夜里不敢独自上厕所……她们都会按响索菲亚的门铃。</p><br/><p>&nbsp;&nbsp;“我是什么时候成为保姆的？！”当索菲亚意识到这个问题的时候，伦茨与艾莉卡正在她的房间里和机器人一起玩着过家家。</p>",
		name = "【科学先锋】",
		story1 = 20210105
	},
	[20210106] = {
		dec = "<p>&nbsp;&nbsp;要说有什么人能让“黑街女王”辛西娅闻之色变，恐怕只有那位特立独行的魔术师——菲娅了。</p><br/><p>&nbsp;&nbsp;故事发生在 2048 年的复活节，辛西娅也难得给自己休了次假，走在拉弥亚街道上的她被一个神秘的招牌吸引——巨大的红玫瑰下绘着四个烫金大字“魔术表演”，想到自己很久没有娱乐过了，辛西娅决定走进那个黑漆漆的剧场。</p><br/><p>&nbsp;&nbsp;很快，带着一顶镶有玫瑰帽子的魔术师登场了，起初，表演并没有让辛西娅感到惊奇，毕竟对经历过各种激烈实战的黑街女王来说，舞台上的那些爆破只能算是小打小闹。</p><br/><p>&nbsp;&nbsp;正当辛西娅即将进入梦乡之时，台上的魔术师忽然邀请她参与魔术“电锯活人”。“原来魔术师请的观众不全是托啊。”这么想着的辛西娅对这位魔术师产生了兴趣，然而，很快这份兴趣就转化成了悔恨。</p><br/><p>&nbsp;&nbsp;首先，当辛西娅躺进舞台上的黑盒子里时，她就感受到了不对劲。在她的知识体系里，“电锯活人”是一种障眼法魔术。人躺在黑盒子里，实际上下半身是隐藏在盒子下方的，舞台上观众能看见露出的腿，是事先安排的假腿才对——但自己平躺在盒子里，意味着电锯真的要从身体穿过，这是怎么一回事？</p><br/><p>&nbsp;&nbsp;接着，魔术师的话语也让她感受到了不安。“若有内脏飞出的情况，还请前排观众谅解。”这时，辛西娅的额头已经渗出了些许汗珠。</p><br/><p>&nbsp;&nbsp;然后，最终的绝望来临了。带着引擎轰鸣声响的巨大电锯，向辛西娅的腰部袭来，速度丝毫没有减弱的迹象。她本能地发出尖叫，然而观众们把这当做是节目效果的一环，喝彩声愈加响亮起来。</p><br/><p>&nbsp;&nbsp;后来，辛西娅似乎就没有记忆了。人类对消失恐惧的本能，让她的大脑无法正常运转。等到回过神，她正被菲娅从黑盒子里扶出来，浑身都是冰冷粘稠的汗液，想要说话时，发现声音也嘶哑了。</p><br/><p>&nbsp;&nbsp;想必刚刚的表演中，自己的惨叫和挣扎就没有间断过，黑街女王何时受过这种屈辱！更可气的是，自己没有任何的理由向那个魔术师发泄……满溢羞耻与愤怒，让辛西娅的泪腺失控了。</p><br/><p>&nbsp;&nbsp;后来得知，魔术使用的电锯是投影的，辛西娅努力地让自己忘却这段不愉快的经历。但是在学院里看见菲娅时，辛西娅扭曲的表情证明，她或许患上了魔术创伤性应激障碍。</p>",
		name = "【黑街旧识】",
		story1 = 20210106
	},
	[20210107] = {
		dec = "<p>&nbsp;&nbsp;最近，皮卡对“淑女”这个词产生了兴趣。她努力地改掉自己任性的坏毛病，不再赖床，不再急性子，主动为姐姐奥德莉承担家务，甚至订购了女性杂志来学习流行语、礼仪和穿搭。那个孩子气的皮卡，忽然发生如此改变，让所有人都吓了一跳。但仔细一想也合情合理，毕竟皮卡也到了在意他人看法的年纪了，无法否认这是好的变化。所以，善良的大家纷纷对皮卡表示赞赏与鼓励，也许魂器学院成熟的女孩子要多一位了。</p><br/><p>&nbsp;&nbsp;然而，大伙还是过于乐观了，皮卡很快就在鼓励的声音中飘飘然。她坚信经过了一周的训练，如今的自己就是最标准的淑女，甚至还拉来了芭荼荼与珍妮特来介绍自己的“淑女经验”。</p><br/><p>&nbsp;&nbsp;“合格的淑女，能够驾驭的不只是短裙，还有家务和料理！”</p><br/><p>&nbsp;&nbsp;起初，芭荼荼和珍妮特都学得非常认真，直到皮卡亲自做了一道料理——那散发着古怪酸气的绿色浓汤，让芭荼荼开始产生怀疑。但是，出于照顾皮卡感受的原因，二人都没有说出自己的真实想法，皮卡的“淑女课堂”仍在继续。</p><br/><p>&nbsp;&nbsp;后来事情的终止，是由于奥德莉的一次出差。出差前，皮卡信誓旦旦地对姐姐保证，自己能处理好家务，还会在姐姐回来的时候为姐姐准备一顿豪华大餐。</p><br/><p>&nbsp;&nbsp;七天后奥德莉回来时，看到的却是在厨房里和面粉融为一体的皮卡——她犹如雪人一般，浑身沾满了厚厚的白色面粉。据皮卡交代，她原本是想像淑女一样做蛋糕来着，但发现实际操作远比自己想象的要复杂，所以才搞成了那样。</p><br/><p>&nbsp;&nbsp;自那以后，就再也没听过皮卡提淑女二字了。</p>",
		name = "【小淑女同盟】",
		story1 = 20210107
	},
	[20210108] = {
		dec = "<p>&nbsp;&nbsp;“御三家”这个名字，是艾丝翠德为卡米拉、芭荼荼和诺诺妮娅取的。</p><br/><p>&nbsp;&nbsp;事情的起因是 人工智能 在奥杜因的边界建立了新的生产据点，若是不能及时铲除，人工智能 的兵力将会在短时间内迅速膨胀。虽然军方已经开始压制，但效果微乎其微。据前线部队发来的资料显示，人工智能 在据点建造了数个新材料壁垒，该材料有着极高的物理强度，军方的所有弹头都无法造成有效伤害，高能激光也无法奏效，于是寻求魂器学院的帮助。</p><br/><p>&nbsp;&nbsp;这让学院的战术老师也为了难，尽管有着魂智能武器，但以伤害属性来说，学员们的能力还是以物理或激光为主，想要临时组建一支机动部队，不是那么简单的事情。</p><br/><p>&nbsp;&nbsp;后来，艾丝翠德通过学生会，给战术老师送了一张小纸条，上面写着：“卡米拉、芭荼荼和诺诺妮娅”</p><br/><p>&nbsp;&nbsp;这个组队方案，让战术老师眼前一亮。但同时也有人提出质疑，担忧卡米拉和诺诺妮娅的配合问题。毕竟这两位学员，一位是“嗜火如命”、一位是“嫉火如仇”，在学院里就闹过不少矛盾。艾丝翠德却对这个方案十分有信心，她认为芭荼荼的认真性格能有效制衡卡米拉与诺诺妮娅。</p><br/><p>&nbsp;&nbsp;“一定没问题的，毕竟是御三家。”</p><br/><p>&nbsp;&nbsp;当时没有人听明白什么是御三家，但是任务成功的一周后，有人发现艾丝翠德的游戏账号里，三只不同属性的宠物精灵，名字分别是卡米拉、芭荼荼和诺诺妮娅。</p>",
		name = "【御三家】",
		story1 = 20210108
	},
	[20210109] = {
		dec = "<p>&nbsp;&nbsp;深夜，因为无力支付高昂的电费，没有人家开着照明，路灯也年久失修，贫民窟的街道漆黑一片。</p><br/><p>&nbsp;&nbsp;莱拉站在医院前的土地上，泥水沾满了裤脚，身上也被大雨淋透。在此之前，她已经在这里站岗了三天三夜。</p><br/><p>&nbsp;&nbsp;起因是为救自己的伙伴——一只名为“罗宾汉”的流浪狗，莱拉来到医院，却对夸张的医疗费束手无策。</p><br/><p>&nbsp;&nbsp;穿着从未洗过、已经不能称之为“白”大褂的外套的医生，将廉价香烟的刺鼻烟雾吐到莱拉的脸上，似笑非笑地说：“如果你真的想救这条狗，那就打工来换医疗费吧。最近街道不太平，为我站三天的岗，我就帮你看看。”</p><br/><p>&nbsp;&nbsp;鞠躬道谢后，莱拉按照约定，在医院前站了三天三夜。可就在第四天的早晨，还是在那廉价香烟的烟雾里，医生告诉她“罗宾汉”已经死掉了。</p><br/><p>&nbsp;&nbsp;“站岗三天折算的药费，就只有那么点效果。要怪就怪自己没钱，贫民窟的家伙。”</p><br/><p>&nbsp;&nbsp;看着自己为“罗宾汉”准备的水与食物没有一点变化，莱拉清楚这名医生非但没有对“罗宾汉”做任何的治疗，就连水和食物也没有给它喂过丝毫。</p><br/><p>&nbsp;&nbsp;那之后，莱拉就在雨地里站到了现在。眼泪早已与雨水混在一起，唯有被牙齿咬破嘴角而渗出的鲜血，能看出她的情绪。</p><br/><p>&nbsp;&nbsp;不知过了多久，一把伞出现在莱拉的头顶，因为身高比莱拉矮不少，举伞的少女显得有些吃力。</p><br/><p>&nbsp;&nbsp;“暗夜的眷属啊，告知吾，汝在此地，是在守护着什么？”</p><br/><p>&nbsp;&nbsp;“没有了……已经没有了……我要守护的东西……罗宾汉……还有正义也是……”</p><br/><p>&nbsp;&nbsp;“连自己都无法救赎的正义，可不能算是正义。对吾来说，恶人必须遭受恶报，这便是吾——弗拉德十七世的正义。”</p><br/><p>&nbsp;&nbsp;停顿片刻，举伞的少女接着说道：“倘若汝仍怀有骑士之心，吾可以将吾之正义赐给汝。做吾的骑士吧。”</p><br/><p>&nbsp;&nbsp;莱拉很奇怪，自己明明满心想着回答少女，身体却自顾自地抽泣，讲不出任何话语。</p><br/><p>&nbsp;&nbsp;“吾明白了。契约成立。”然而那名少女，似乎已经听见了自己内心的答案。</p>",
		name = "【伯爵与骑士】",
		story1 = 20210109
	},
	[20210110] = {
		dec = "<p>&nbsp;&nbsp;第九十五届耶梦加得运动会，雯第一次作为运动员登场了。</p><br/><p>&nbsp;&nbsp;在此之前，派森的教练已经来到魂器学院拜访了三次，一开始极力拒绝的雯终于心软，向学院请了三天的假，答应教练在比赛当天前往耶梦加得。</p><br/><p>&nbsp;&nbsp;从未有过大赛经验的雯，向学院里的几位运动健将讨教经验。她们分别是维卡、凯茜以及多莉丝。</p><br/><p>&nbsp;&nbsp;擅长弓箭的维卡，还有回旋镖大师凯茜，都告诉雯关于精准的技巧；而多莉丝，则是带着雯在街头球场打了一天的球，让性格内向的雯不再紧张怯场。</p><br/><p>&nbsp;&nbsp;时间与镜头切换至耶梦加得运动会标枪项目的比赛现场，派森的教练紧握着雯的手，激动得像抓住了救命的稻草。</p><br/><p>&nbsp;&nbsp;“雯，真的很感激你。派森的标枪队已经有四届运动会没进入过决赛……这是教练我的责任……然而我还是想在明年退休之前，看到咱们的队伍拿一次奖牌……请原谅我的这一点私心……现在第二名的成绩是一百二十米，那么，我们的目标，就是一百二十米，能拿到奖牌就好……也许有些过分，但还是拜托你了，雯选手！”</p><br/><p>&nbsp;&nbsp;雯微笑着点点头，奋力一掷，经过短暂的飞行，标枪稳稳地扎在了一百二十米的标线上。</p><br/><p>&nbsp;&nbsp;场边沸腾了，派森的运动员们欢呼雀跃，她们涌向赛场，将雯团团围住，一个接一个与雯紧紧拥抱。</p><br/><p>&nbsp;&nbsp;然而，观众席上前来为雯加油打气的同学却沉默了。因为大家都知道雯在魂器学院时，用标枪可以随意命中两千米的目标。</p><br/><p>&nbsp;&nbsp;“我说，雯是不是理解错了教练的意思，‘目标是一百二十米’，并不是那个命中‘目标’的‘目标’啊……”维卡尴尬地说道。</p>",
		name = "【运动少女】",
		story1 = 20210110
	},
	[20210111] = {
		dec = "<p>&nbsp;&nbsp;本学期的“尖兵勋章”，将会颁发给玛琉、塞雅、凯茜以及伊莉莎四位学员，因为她们在今年完成了一个近乎传奇的任务，被誉为“尖兵四十五天”。</p><br/><p>&nbsp;&nbsp;故事发生在十二月的奥杜因，作为曾经的“世界工厂”，钢筋森林一般的奥杜因有着世界上最复杂的地下通路。由玛琉、塞雅、凯茜和伊莉莎组成的四人小队，刚刚在核心区域获取了新型 征服者动力机甲的情报，正在通过地下通路进行撤退。</p><br/><p>&nbsp;&nbsp;奥杜因地下通路最深处的深度有四百米，几十层通道立体交错，覆盖面积达上百万平方公里。魂器学院用半年时间收集资料、开发完成的导航系统，也显示需要七天才能完成撤退。但即便如此，地下通路比起地面路线还是有着绝对优势，例如 人工智能 的无人机和大型机械部队无法进入，监控数量也要少得多，于是小队还是决定利用地下通路撤退。</p><br/><p>&nbsp;&nbsp;然而未曾设想过的危机忽然降临，模拟智能系统 指挥 人工智能 对地下通路投掷了脉冲炸弹，这是一种能摧毁所有电信号系统的武器，直接让小队持有的导航无法运作，但对 人工智能 来说这也是一种自毁攻击，因为同样的，人工智能 在地下通路部署的机器人部队也悉数被毁。模拟智能系统 不惜自损来阻止魂器学院小队的撤退，因为她们带走的那份情报实在是太重要了。</p><br/><p>&nbsp;&nbsp;没有了导航与所有电子设备的玛琉小队，意味着切断了与学院的联系，在无法接受支援的情况下，需要步行走出那冰冷、黑暗的地底世界。温湿度保持系统与照明系统全部失效，此刻的地下通路就是绝望地狱。</p><br/><p>&nbsp;&nbsp;这是一场持续了四十五天的奇迹，塞雅与玛琉是出身于军方的特种兵，伊莉莎有着野兽一般的五官感知力，凯茜则有着极强的方向感。小队成员使出浑身解数，终于在四十五天后走出地下通路，完成了这一场惊险的“地底求生”。情报完整带回，全体成员安全撤退，这四位学员，是当之无愧的“尖兵”。</p>",
		name = "【尖兵】",
		story1 = 20210111
	},
	[20210112] = {
		dec = "<p>&nbsp;&nbsp;露缇将她的魂智能武器“造物之主”放在训练室保养，这让索菲亚两眼放光。</p><br/><p>&nbsp;&nbsp;一直对露缇头上的巨手感到好奇的她，科学家之魂瞬间被点燃，索菲亚决定趁此露缇不在的机会，对造物之主展开研究。</p><br/><p>&nbsp;&nbsp;众所周知，每个魂武都需要学员各自的“灵匙”才能启动，但“造物之主”似乎是特别的。它果断响应了索菲亚的请求，在索菲亚按下露缇手柄的按键后，慢慢浮到了上空。</p><br/><p>&nbsp;&nbsp;索菲亚强忍激动，试着通过手柄输入指令，摸清了“造物之主”的行动逻辑后，又找来了黎波娜帮忙，想要进一步研究“造物之主”的内部构造。</p><br/><p>&nbsp;&nbsp;可就在她们碰到第一个螺丝时，“造物之主”自行行动了起来。它不顾索菲亚的“停止”指令，三只手来回舞动——不一会，就用手末端连着的线将索菲亚和黎波娜捆到了一起，任凭两人各种挣扎，线也没有松动的迹象，反而因为动作的扭曲，让索菲亚和黎波娜的四肢交缠在一起，形成了一副滑稽的模样。</p><br/><p>&nbsp;&nbsp;两个小时后，露缇回到训练场，看着眼前两位同学的狼狈景象，叹了一口气：“歌德，你玩过头了啦。”</p><br/><p>&nbsp;&nbsp;原来，一开始“造物之主”会响应索菲亚的指令，只是它自己主动的行动而已。能把天才科学家索菲亚刷成这样的，还是头一遭。</p><br/><p>&nbsp;&nbsp;不过，能够独立于魂姬自己行动，这进一步增添了“造物之主”的神秘感。索菲亚对它的兴趣更高了。</p>",
		name = "【操作达人】",
		story1 = 20210112
	},
	[20210113] = {
		dec = "<p>&nbsp;&nbsp;来自洛加尔的电玩冠军艾丝翠德与奈奈，最近准备进军虚拟现实电竞领域。</p><br/><p>&nbsp;&nbsp;艾丝翠德与奈奈两人，已经拿了无数个游戏竞技奖项，可以说，只要是用手柄操控、在屏幕上进行的游戏，就是二人的表演的舞台。电玩大赛进行到最后，由艾丝翠德与奈奈进行决赛，已经是游戏爱好者们司空见惯的景象。</p><br/><p>&nbsp;&nbsp;可是，追求新鲜与刺激是游戏玩家的天性，纵然已经站在电竞领域的定点，艾丝翠德与奈奈仍在寻求新的赛场——最近洛加尔举办的“虚拟现实 终极格斗大赛”，就是理想的新天地。</p><br/><p>&nbsp;&nbsp;艾丝翠德与奈奈参赛后，事情没有超出大家的预料。两位天才玩家，凭借着多年以来积累的游戏理解与超人的天赋，在新的 虚拟现实 领域仍是呼风唤雨，一路击败来自其他都市的选手，最终来到了决赛。</p><br/><p>&nbsp;&nbsp;决赛形式是四人的大乱斗，与往常一样，艾丝翠德与奈奈花了全部精力研究彼此的战术，并没有把另外两名选手纳入考虑。因为按照以前的经验，只要是有她们两人在的赛场，其他人就只能够担任炮灰的角色。</p><br/><p>&nbsp;&nbsp;然而本次“虚拟现实 终极格斗大赛”，显然超出了她们的预计。决赛里忽然杀出的白骑士，三下五除二，将包含她们在内的三名玩家悉数斩落。与其说是大乱斗，不如说决赛完全是那名白骑士的个人秀。</p><br/><p>&nbsp;&nbsp;最后，当白骑士摘下头盔，情况更是让艾丝翠德与奈奈傻了眼——那纯白的头盔之下，是妮妙的脸。她平静得连一滴汗都没有出。</p><br/><p>&nbsp;&nbsp;“虚拟现实 终极格斗大赛”，成了艾丝翠德与奈奈的滑铁卢。但她们没有因此受到打击，反而因为发现了强力的对手，燃起了空前的斗志。</p>",
		name = "【电玩之星】",
		story1 = 20210113
	},
	[20210114] = {
		dec = "<p>&nbsp;&nbsp;最近，学院里有着模特般傲人身材的学员越来越多，她们亭亭玉立，凹凸有致，一直对自己发育不够满意的远坂秋看着她们，暗暗起草了一份计划。</p><br/><p>&nbsp;&nbsp;假期里的一天，远坂秋请来那须野红叶、雅娜黛茜亚以及芙蕾一起逛街游玩。远坂秋认为，她们能够塑成如今这般令人羡慕的身材，一定不全是基因的问题。她想记录下三人的习惯、爱好，还有吃东西的口味，找到共同点，那一定就是自己迫切需要的“发育之法”。</p><br/><p>&nbsp;&nbsp;四人来到餐厅，拿到菜单后，远坂秋就立即进入了“侦查模式”。她认真记录下三位“模特”同学的点单，结果却让她为难起来：红叶选择了霸王肉片盖饭，芙蕾则是一份清汤面，而雅娜黛茜亚是汉堡套餐——非但预想中的牛奶没有出现，三人的口味还大相径庭，完全没有共同点。</p><br/><p>&nbsp;&nbsp;接着，远坂秋带她们聊起了运动的话题，结果再次让她头大：雅娜黛茜亚很喜欢足球；活泼的红叶没有专门训练过某项运动；芙蕾则是不喜欢运动，因为身材给她带来了一些不便…</p><br/><p>&nbsp;&nbsp;就这样，直到最后，远坂秋都没能找到自己想要的“发育之法”。一直坚信后天努力能够扭转先天条件的远坂秋，信念受到了打击。</p>",
		name = "【成熟的味道】",
		story1 = 20210114
	},
	[20210115] = {
		dec = "</p>&nbsp;&nbsp;说到魂器学院的学园祭，就不得不提获得今年特别奖的那家店铺。</p><br/><p>&nbsp;&nbsp;名字是“动物咖啡厅”，原以为会在咖啡厅里与小动物相处的大家，打开门后，看到的却是满面羞红的艾莉卡、充满热情的伊卡洛维以及做着鬼脸的洛卡娜。</p><br/><p>&nbsp;&nbsp;原本的惊讶，很快就在三名可爱女孩一齐的“欢迎光临”声中烟消云散，没有人能抵挡住这份治愈的威力，开门后的短短一小时，“动物咖啡厅”门外的队伍就已经排到了五十米。</p><br/><p>&nbsp;&nbsp;唯一遗憾的是，如果伊卡洛维没有偷吃食材、洛卡娜没有失手打破盘子，“动物咖啡厅”本还可以多招待一些人的。</p>",
		name = "【猫！狗！兔！】",
		story1 = 20210115
	},
	[20210116] = {
		dec = "<p>&nbsp;&nbsp;“恭喜您成为新一代白色彩虹糖的幸运代言人！全世界只有两名顾客获得此机会！请于 2049 年 1 月 1 日前联系厂家，厂家将会对您进行全套包装，还会带您前往世界各地拍摄多个宣传片……”——伊迪斯和缇法打开自己的零食包装袋后，一只跳出来的微型机器人、不停投影着这样的文字。</p><br/><p>&nbsp;&nbsp;全世界只有两个名额，还全部在魂器学院里，这事发生的概率并不比太阳从西边出来高多少。</p><br/><p>&nbsp;&nbsp;实际上，这是爱丽丝的安排。</p><br/><p>&nbsp;&nbsp;做生意的友人请爱丽丝推荐形象代言人，企业的新产品白色彩虹糖，想要有与白色特别相配的女孩来代言——就在说出请求的半秒后，爱丽丝联想到伊迪斯和缇法。</p><br/><p>&nbsp;&nbsp;但事发突然，很难保证伊迪斯和缇法会答应这件事——让还没从学校毕业的未成年女孩做如此抛头露面的事情，的确有些为难。</p><br/><p>&nbsp;&nbsp;于是，爱丽丝想了一个办法，在伊迪斯和缇法的零食袋里放入了自己制作的机器人，让她们相信这是厂商的活动。</p><br/><p>&nbsp;&nbsp;免费的旅游加明星团队的摄影、包装，对任何女孩而言都是难以拒绝的。</p><br/><p>&nbsp;&nbsp;也许不久后，就能看见印着伊迪斯和缇法漂亮照片的彩虹糖上市啦！</p>",
		name = "【白色小女团】",
		story1 = 20210116
	},
	[20210117] = {
		dec = "<p>&nbsp;&nbsp;玛姬又受伤了。</p><br/><p>&nbsp;&nbsp;这是这个月以来的第三次，不过比起前两次，稍微要严重一些。</p><br/><p>&nbsp;&nbsp;头部缝了七针，被纱布紧紧包着；右手指关节错位，不过这是因为她揍人太用力导致的。</p><br/><p>&nbsp;&nbsp;“该死的家伙，真是阴险。”醒来的第一时间，玛姬感受到伤口的疼痛，下意识骂了一句。</p><br/><p>&nbsp;&nbsp;试着回想昨晚的景象，那是库库尔坎的奶茶吧门口，可怜的女孩躺在地上，一边的男子正对她拳打脚踢。</p><br/><p>&nbsp;&nbsp;“老子辛辛苦苦介绍你去奶茶吧上班，你就给我这点回报？快点把薪水都拿出来，再不老实，就把你——”</p><br/><p>&nbsp;&nbsp;“就把她怎么样？”</p><br/><p>&nbsp;&nbsp;“咦——呜哇！”</p><br/><p>&nbsp;&nbsp;面对忽然出现的玛姬，男人还没来得及理清状况，就被一脚踹倒在奶茶吧门前的台阶上，接着就摸着屁股的位置，呻吟不止。</p><br/><p>&nbsp;&nbsp;眼看男人暂时没法动弹，玛姬回头想拉起女孩，却被突然而来的奶茶瓶从后方砸中了头部。</p><br/><p>&nbsp;&nbsp;后面的事情就有些模糊了，似乎是身体本能地发起反击，玛姬将男人摁倒后，用拳头揍碎了他全部的牙。而等到再次醒来后，玛姬就躺在了魂器学院的医务室。</p><br/><p>&nbsp;&nbsp;现在，玛姬感到头越来越痛，病床上的消毒水味让她非常难受。她挣扎着站起，走到窗边，疼痛果然就减轻了很多。</p><br/><p>&nbsp;&nbsp;但减轻玛姬疼痛的并不是新鲜空气，而是通过窗户传进来的清脆歌声——琉璃和梅洛迪，正在楼下的音乐室里练习着她们原创的曲子。</p><br/><p>&nbsp;&nbsp;若是以往，玛姬一定已经不耐烦地关上了窗，但现在她却发现自己不忍离开，少女的歌声似乎有着一种自己无法理解的魔力，将自己黏在了原地。就这样，玛姬在窗边一直站到了乐器声停止。玛姬觉得自己的脑子被敲坏了。</p>",
		name = "【音乐疗法】",
		story1 = 20210117
	},
	[20210118] = {
		dec = "<p>&nbsp;&nbsp;关于因果幸运的传说，在她刚进入学院的时候就开始流传了。</p><br/><p>&nbsp;&nbsp;高空摔下的花盆离她一步之遥，飞速行驶的车辆和她擦身而过，连穷途末路之际都意外出现了转机……总之，事情是越传越离奇，不久前人类登陆火星成功，似乎都是因果的功劳。</p><br/><p>&nbsp;&nbsp;“总觉得现在，有些过分了啊……”康茨坦丝扶了扶额头。因为每次在考试前，要“摸一摸因果以求好运”的人，越来越多了。昨天的小测试，排队摸因果的队伍已经从教学楼三楼排到了二楼。为此，学生会找到因果，想商量出解决办法，化解大家对运气的迷信。</p><br/><p>&nbsp;&nbsp;最终的结论是，召集大家后，让金百莉对着因果射击。使用的左轮枪里装有一枚红颜料弹和五枚白颜料弹，若是白颜料弹打中因果，就能让大家明白因果的幸运并不是绝对的——实际上为了以防万一，金百莉还会提前将枪换掉，用全部都装有白颜料弹的手枪表演射击，这样无论如何，结果都会像学生会设计的那样，命中因果的，只会是白颜料弹。</p><br/><p>&nbsp;&nbsp;因果也答应了，毕竟这样解开迷信，才算是真正帮助到大家。</p><br/><p>&nbsp;&nbsp;表演当天，一切顺利，金百莉悄悄将枪换成全白颜料弹的一把，然而就在扣动扳机的时刻，左轮枪哑火了。</p><br/><p>&nbsp;&nbsp;教学楼瞬间犹如开水般沸腾，因果在此刻彻底成为了大家心中的幸运之神。</p><br/><p>&nbsp;&nbsp;金百莉、因果和学生会的大家却迷惑了，像这样事情不如因果所想的那样发展，到底算是她幸运还是不幸运呢……</p>",
		name = "【左轮枪与运气】",
		story1 = 20210118
	},
	[20210119] = {
		dec = "<p>&nbsp;&nbsp;“今天也一起打棒球吗，夏洛特？”多莉丝略带不耐烦地问到，“要不，今天和我一起去玩玩滑板~”见她们没有回答，多莉丝又自己往下说了。“要是去的话，我可以让你们看看我最近刚练的踢翻。”多莉丝也不在意有没有回音，继续陶醉在自己的世界里。“要知道，我可是不轻易好为人师的，既然你们这次要参加我的街头派对，那我可得教你们一些脚下功夫。不然传出去，可是会被人瞧不起的……”</p><br/><p>&nbsp;&nbsp;夏洛特理了理自己的头发，又摆正了自己琴包的位置，保证它不会因为大幅度的动作而滑落。她又低头看了看自己今天新做的美甲。嗯，还是挺漂亮的，琉璃那家伙推荐的店和款式，意外的，让这个处在叛逆又温和的少女心满意足。“那个……“夏洛特终于忍不住打断了正在激情普及滑板赛事和展望未来能够一下团队比赛的多莉丝。拉普拉斯这时候，一改她阴沉的脸，难得地露出了一丝诡谲的微笑。仿佛，像是在享受即将到来的快感。“我还是想，今天还是和琉璃一起排练一下新歌……”</p><br/><p>&nbsp;&nbsp;“喂喂，是不是有点令人扫兴了啊。</p><br/><p>&nbsp;&nbsp;“那我刚才说了一堆，岂不是都是在……自言自语？“</p><br/><p>&nbsp;&nbsp;“嘿嘿嘿。”这时候从拉普拉斯的嘴里透出的笑声更加刺激了多莉丝的情绪。多莉丝倏地一下就红了脸，像个做错事的孩子一样。作为街区里的小头目，之前多莉丝哪有受过这样的冷落和嘲笑，当即一脚踢起了脚边的滑板，就想准备从这个尴尬的环境中逃开。</p><br/><p>&nbsp;&nbsp;但是，缺也找不到什么好理由，就这样拉下脸离开。这样不就是会被她们看不起，脸皮子薄、气量小吗！多莉丝只好，把滑板踩起、又放下，来来回回。</p><br/><p>&nbsp;&nbsp;“要不……今天的社团活动就，就先结束？“</p><br/><p>&nbsp;&nbsp;“你们真的还就把这个当作社团活动了！”多莉丝突然就像刚被捕捞上岸的鱼，试着挣扎了两下，又像自讨没趣的样子，闭上了嘴。“真正的，真正的街头不良才不是这样子呢！”</p><br/><p>&nbsp;&nbsp;“墨格尔的混乱，还是没有巴哈姆特来得有趣呐。”这时候拉普拉斯才开始打起了精神，满怀笑意地说道。“下次申请一下外出许可，我带你们见识一下什么叫做真正的不良，哈哈哈，我可是有着很多手下的呢。“</p><br/><p>&nbsp;&nbsp;“拉普拉斯，你就别吹了吧。就你那些杂鱼，还不如我们炫速帮呢。”</p><br/><p>&nbsp;&nbsp;“下次叫出来比试比试啊。”</p><br/><p>&nbsp;&nbsp;“来就来，谁怕谁啊！”</p><br/><p>&nbsp;&nbsp;“不来的人是小狗！”</p><br/><p>&nbsp;&nbsp;“略略略，汪汪叫。“</p><br/><p>&nbsp;&nbsp;夏洛特心想，也许叛逆，才是真正的不良吧，Rock~</p>",
		name = "【不良少女】",
		story1 = 20210119
	},
	[20210120] = {
		dec = "<p>&nbsp;&nbsp;“你确定，不会被卡米拉抓到吗？”</p><br/><p>&nbsp;&nbsp;“我们这个是正规的地质实验，和康斯坦茨会长走过流程的。”</p><br/><p>&nbsp;&nbsp;“哦哦，那就好。”说罢，洛卡娜便将一个大盒子放在了操作台前，脸上露出了担忧和自豪的复杂情绪，她就像一只警惕的小兔子，生怕稍稍不留神就成为盘旋猎鹰的果腹之食。</p><br/><p>&nbsp;&nbsp;“好。”火羽戴好实验手套，小心翼翼地从防护盒里拿出乌黑的石头。不得不说，洛卡娜能够搞到这样保存完整，甚至可以用新鲜来形容的火山岩，简直值得称赞和夸奖一番。当火羽碰上岩石，学员们都知道，这就是饿上了三四天的马匹碰上了青青草原——拉都拉不住。也许这就是一个学者对于知识渴求原本的样子吧。这样执着的热情，同样也打动了对“石头”毫不感兴趣的洛卡娜。</p><br/><p>&nbsp;&nbsp;“那么，现在开始第一次分析实验。</p><br/><p>&nbsp;&nbsp;“现在是最基本的外形勘察，颜色总体呈现乌黑色，但更偏向于土灰色发展。从形态学上来看，并非是火山熔岩，而更靠近火山碎屑岩。以初步观察来看，火山碎屑物体积分数大于百分之九十，正常沉积物和熔岩物质较少…“</p><br/><p>&nbsp;&nbsp;“火羽姐姐，这个是你想要的吗？”洛卡娜看在一旁看着火羽对着自己带来的石头仔细的观察，说着自己不太懂的话，洛卡娜不知道自己带来的东西到底对于她来说，是好还是不好。</p><br/><p>&nbsp;&nbsp;“谢谢你，这个样本很不错。这是你在家乡附近采集的吗？”</p><br/><p>&nbsp;&nbsp;“是的，费了好大的功夫呢~”洛卡娜开心地不由大声了起来，随后看了看周围情况，又小声地问火羽，“火羽姐姐，什么事火山碎屑岩呀？”</p><br/><p>&nbsp;&nbsp;“嗯，火山碎屑岩其实也是火山岩其中的一种分类。它和火山熔岩不一样，它主要是爆发式火山活动时产生的碎屑通过空气或水介质堆积后，经过成岩作用形成的岩石。”火羽带着防护手套不断从不同角度摆弄着那块仿若珍宝的石头，“通过恒温箱带来的样本，摸起来仍有些余温。看来，可能还是熔结火山碎屑岩亚类…”</p><br/><p>&nbsp;&nbsp;“女人啊，你们可是在玩火~”突然一个声音打破了火羽专注的研究思路。只见，诺诺妮娅神不知鬼不觉地就出现在了门口。诺诺一把抱住了洛卡娜说：“你们玩火也不叫上我，亏我们的属性还那么相似呢~”</p><br/><p>&nbsp;&nbsp;“唔…我们是在探索世界。”洛卡娜试着睁开诺诺的环抱，但是无果，只得头口抵抗一下，“才不是要燃烧整个世界呢。”</p><br/><p>&nbsp;&nbsp;“哔哔！”</p><br/><p>&nbsp;&nbsp;突如其来的警哨打破了对话，只见卡米拉冲了进来，“我就知道！你们！你！还有你！竟然还有你！你们聚·众！是不是在商量与火有关的事！”</p><br/><p>&nbsp;&nbsp;“啊，别我和康茨坦丝申请过的…”火羽的声音随着卡米拉手中的消防灭火器冲刷试验台上火山岩的流水声越来越小，仿佛热情之火也被一并浇熄了…</p><br/><p>&nbsp;&nbsp;虽说星星之火可以燎原，但是只要卡米拉在…火是不会变成炎焱燚的。</p>",
		name = "【火炎焱】",
		story1 = 20210120
	},
	[20210121] = {
		dec = "<p>&nbsp;&nbsp;江湖上流传着一个……不，应该学院里流传着这样一个传说——</p><br/><p>&nbsp;&nbsp;时逢天下受乱，百姓无端被名为人工智能的祸首屠戮，民不聊生。虽各地皆有能人异士揭竿而起，维护正常生活的一方小天地。派森，是个不缺少传说和奇人的地方。有黑暗，就会有光芒。就在官方尚未顾及到的小地方，百姓仍处在水深火热的境地之中。这时，江湖上就出现了四位暗中保护百姓的侠客。哪里有人工智能压迫，哪里就有她们。</p><br/><p>&nbsp;&nbsp;据闻，为首的侠客雷厉风行、拳下生风，很少有人工智能能在她的拳下走过三招。曾以一式“天麟拜月”威震四和，嘴边常挂“强者就该与强者交手”而行走天下。人工智能若想与之比拼拳脚，定不是她的对手。得救的百姓，便称此侠客为“拳天师”。</p><br/><p>&nbsp;&nbsp;而另有人工智能想近身不行，那么便来远的。在远处就能限制拳法的发挥，那么它们可就答错特错了，在拳天师的背后，还有一位默默守护团队的狙射能手。既然是狙射能手，可又何谓之侠呢？穿林入云，踪影难觅。古道热肠，嫉恶如仇。此者不以冠之侠，何者可称侠呢？遂人称之为“竹林怪客”。</p><br/><p>&nbsp;&nbsp;且放眼天下，贪财者浩如烟尘。而行侠不求回报者，甚少。</p><br/><p>&nbsp;&nbsp;此有只顾铲除奸邪人工智能者，只求一口热乎肉包，如此侠道热肠，不得不拍手称快。更有且饮微醺，就能持剑戏人工智能，除暴惩奸。起初，百姓还担心虚弱脚下无力，如走云端。未曾想她轻舞如常，剑技雄浑。便有人赞曰“画中仙”。</p><br/><p>&nbsp;&nbsp;此四侠行走天下，救济苍生。行尽善事，未曾留名。芳踪何觅，远山白云间。但是谁说四侠就只有四个人……对吧~</p>",
		name = "【萍踪侠影】",
		story1 = 20210121
	},
	[20210122] = {
		dec = "<p>&nbsp;&nbsp;一杯奶茶，能有几种喝法？</p><br/><p>&nbsp;&nbsp;布兰琪会告诉你鲸吞豪饮，无论什么种类的奶茶、无论多么甜的奶茶，只要是盛在杯子里的，或者再豪放一点，是盛在大容器里。只要它敢被冠名以“奶茶”，那么它就逃不过布兰琪的口舌、逃不过她的喉咙、逃不过她的胃。用布兰琪的话来说，就是“喝奶茶，不就是为了奶茶精过喉后的那一声爽快的‘哈’吗”。</p><br/><p>&nbsp;&nbsp;艾玛则会告诉你，优雅的喝奶茶，才是饮奶茶的极致。奶茶杯在盛装调奶茶师精心调制的多颜色或者单色的奶茶，再点缀上怡人的杯奶茶装饰，慢慢地品味饮料和奶的混合。那样的滋味才叫美妙人生。再配合上曼丽的音乐，听调奶茶师为你诉说一杯杯不同鸡尾奶茶的趣闻和命名史。这样的放松，才是品奶茶之道。</p><br/><p>&nbsp;&nbsp;“世界上，只有糯米酿成的糯米奶茶才是真正的上品。”李的话，一定会这样告诉你。奶茶，难道不是像水一样吗？每天都需要带在身边，借此来补充水分吗？李的饮奶茶已经不是寻常的“找乐子”式的怡情手段了，而是生活的一部分。</p><br/><p>&nbsp;&nbsp;也许，这也跟她所学的剑术有所关系。最好是能有像她一样的体质，不然过量饮奶茶还是对身体健康有非常大的影响的。你看，除了她意外，布兰琪和艾玛上战场，哪有带着奶茶的。</p><br/><p>&nbsp;&nbsp;别看希艾姆对于青柠绿茶有着自己的执着。但是，私底下好胜的布兰琪经常邀约她去斗奶茶。据说她们之间的成绩是三十三胜三十二负七十六平。布兰琪都直接喊希艾姆为朗姆奶茶女王，说是在朗姆奶茶的品鉴上，学院内暂时还没有人能够超越希艾姆。包括她的奶茶量，也只有布兰琪能够与之不相上下。</p><br/><p>&nbsp;&nbsp;当她们四个人聚在一起的时候，或许只能用派森的一个词语“奶茶池”来形容她们的快乐了。</p><br/><p>&nbsp;&nbsp;不过，请她们能够严格遵守学院医师的指导意见：适度饮奶茶，切勿成瘾。</p>",
		name = "【奶茶皇后】",
		story1 = 20210122
	},
	[20210123] = {
		dec = "<p>&nbsp;&nbsp;“芸儿，你现在在哪里？有盯着那家伙吗？”</p><br/><p>&nbsp;&nbsp;“摩洛娜姐，我现在在黑街附近…我一直盯着那家伙呢。不过……“</p><br/><p>&nbsp;&nbsp;“怎么？”</p><br/><p>&nbsp;&nbsp;“你跟着的学院那个孩子，好像追着那家伙过来了。”</p><br/><p>&nbsp;&nbsp;“哎呀，那个孩子傻乎乎的。对现状了解不是很深，就这样贸然带队来了拉弥亚……”</p><br/><p>&nbsp;&nbsp;“这个就是现在领头势力学院的代表吗？感觉有点不靠谱呢。”</p><br/><p>&nbsp;&nbsp;“不知道布克丝在盘算着什么，既然她会愿意让这个小家伙接手和魂智网络和魂智能武器这些重要的项目，就表明她一定是在小家伙身上赌上了什么。”</p><br/><p>&nbsp;&nbsp;“摩洛娜姐，这个家伙现在被希尔瑞斯围住了……我……“</p><br/><p>&nbsp;&nbsp;“把你的位置发送给我。嗯……我们还有两个街口的距离。</p><br/><p>&nbsp;&nbsp;“如果情况紧急的话，芸儿，就只能麻烦你先出手了呢~”</p><br/><p>&nbsp;&nbsp;“好的。”</p><br/><p>&nbsp;&nbsp;“娜姐，我们来这里，应该不是和魂器学院牵扯上关系吧。”</p><br/><p>&nbsp;&nbsp;“E·S·P应该有更重要的任务不是吗？”</p><br/><p>&nbsp;&nbsp;“幸，芸，你们接到的任务看来是这样的没错。</p><br/><p>&nbsp;&nbsp;“但是，作为小队长来说，一边执行寻找西奥多博士的任务，一边和魂器学院接触，才是我们这次来拉弥亚的目的。”</p><br/><p>&nbsp;&nbsp;“既然是你的判断，我都听你的，娜姐。”</p><br/><p>&nbsp;&nbsp;“我们作为电子稳定计划（Electronic Stability Project）的先遣力量，不仅要优先寻找人工智能变乱的线索，同样，和主流层面势力接触也是需求之一。”</p><br/><p>&nbsp;&nbsp;“摩洛娜姐，嘟嘟说，他们已经开始接近拉弥亚核心区的护盾了。</p><br/><p>&nbsp;&nbsp;“看来这次他们打算硬碰硬。”</p><br/><p>&nbsp;&nbsp;“小家伙们还是年轻呀。这明显就是一出请君入瓮的鸿门宴，一点防范都没有。人会不断学习，但是也别忘记了人工智能也在默默进步呢。</p><br/><p>&nbsp;&nbsp;“想要拯救世界，仅凭一腔热血是不够的呢。这次我们得出马，卖学院一个人情。”</p><br/><p>&nbsp;&nbsp;“娜姐，让我去。”</p><br/><p>&nbsp;&nbsp;“幸，别着急。我和你一起。芸儿你也远处掩护我们。</p><br/><p>&nbsp;&nbsp;“也不知道，借此机会能不能建立起契机，让托拉和学院产生联系。”</p>",
		name = "【电子稳定小队】",
		story1 = 20210123
	},
	[20210124] = {
		dec = "<p>&nbsp;&nbsp;某次生日会。</p><br/><p>&nbsp;&nbsp;“哈喽，玩鸟的。”芸瞪大了双眼，充满了疑惑地看着菲娅。她呆了一会，疑惑地问：“什么叫做玩鸟的？”菲娅耸了耸肩说，“我就随便说说哈哈，你不要在意。”</p><br/><p>&nbsp;&nbsp;“只是我以前观察过，你好像能和身边的小麻雀说话？”</p><br/><p>&nbsp;&nbsp;“它叫嘟嘟，是我的好朋友。”芸也不介意菲娅之前的快人快语，认真地向对方介绍落在肩头的小家伙。</p><br/><p>&nbsp;&nbsp;“其实，我是有个请求。”菲娅竟然有些不好意思起来，“你知道的，对了，你有看过我表演魔术吗？”</p><br/><p>&nbsp;&nbsp;“我知道的。”不知道是不是因为心情好的缘故，芸礼貌地、耐心地等待着对方的下文。</p><br/><p>&nbsp;&nbsp;“那就好。那我就不客套，卖关子了，我直说了。”菲娅放下了心防一般说道，“我想请你做我下一次表演的助手。”</p><br/><p>&nbsp;&nbsp;“我拒绝。”芸警惕了起来，“嘟嘟不是鸽子。”</p><br/><p>&nbsp;&nbsp;“啊，不是不是。我这次不表演大变活物、或者宠物箱无伤魔术。”</p><br/><p>&nbsp;&nbsp;“那，我也拒绝。”</p><br/><p>&nbsp;&nbsp;“为什么！”菲娅左顾右盼，仿佛是揣着什么秘密的一般，轻轻招呼芸靠近一点，生怕技术被人偷了去。</p><br/><p>&nbsp;&nbsp;“这次，我想……你不是会飞刀嘛……你这样，然后我这样，嗯嗯。怎么样？”</p><br/><p>&nbsp;&nbsp;“我可以教你速成，我自己不参加可以吗？”</p><br/><p>&nbsp;&nbsp;“不，可，以。”</p><br/><p>&nbsp;&nbsp;“那我拒绝。”芸无情地再再再次拒绝了菲娅。</p><br/><p>&nbsp;&nbsp;至于菲娅新的魔术表演最后成功了没有，芸上台了没有，我们只能问那些参加了那次欢乐生日会的朋友们了。</p>",
		name = "【光影魔术秀】",
		story1 = 20210124
	},
	[20210125] = {
		dec = "<p>&nbsp;&nbsp;有些艺术品，因为残缺而变得独一无二，乃至世界闻名。唯一的可能有机会变成独特，唯二也有可能变得珍惜，要是数量再多起来的话，那么就要承担泯然众人的风险。所以，有学院询问过伊尔莱丝和斯卡兰斯的组合，为什么是如此的搭配。斯卡兰斯耿直地回答，“原本的人选卡翠欧娜因为工作的原因，拒绝了这次风帆船比赛。</p><br/><p>&nbsp;&nbsp;“而且，伊尔莱丝小姐，对于风向的把握非常有一套，所以我们有把握这次继续连霸。”</p><br/><p>&nbsp;&nbsp;“那么伊尔莱丝小姐，你对赛前有什么祝福的话要送给其他的参赛者呢？”</p><br/><p>&nbsp;&nbsp;“风，告诉我。我们一定会赢的。”</p><br/><p>&nbsp;&nbsp;“好的，谢谢。看来伊尔莱丝小姐和斯卡兰斯小姐对于这次没有卡翠欧娜、没有希艾姆、没有■■■■参加的风帆船比赛很有夺冠的信心。”</p><br/><p>&nbsp;&nbsp;“那么你们可以向小编透露一下，眼睛问题不会影响这次比赛的发挥吗？”</p><br/><p>&nbsp;&nbsp;“这，这个不是因为潮流和耍酷……”伊尔莱丝面对这样的提问，略微有点窘迫和手足无措。也许，让被访者尴尬和呈现出窘态，正是现在电视所需要的节目效果。斯卡兰斯这时候抢过话头，“这个无须担心，就算不便，我们也能够凭借其他的技术手段克服困难，冠军一定是我们的。”</p><br/><p>&nbsp;&nbsp;“对……”</p><br/><p>&nbsp;&nbsp;“那你们的组队，是不是还有因为这样的原因，有点惺惺相惜呢？“</p><br/><p>&nbsp;&nbsp;“英雄惜英雄，美人惜美人，天下常情。”</p><br/><p>&nbsp;&nbsp;“看来之中有很多是不能透露的秘密，那么就祝‘风水独眼侠’队比赛好运了。”</p><br/><p>&nbsp;&nbsp;伊尔莱丝在记者走远之后，有些犹犹豫豫、忸怩的样子。斯卡兰斯见状便问：“怎么了，伊尔莱丝？”</p><br/><p>&nbsp;&nbsp;“你说，我们这个队的名字是不是有点太……太中二了？”伊尔莱丝略微有些脸红，“早知道，就不听爱丽丝和莱拉他们的建议了。”</p><br/><p>&nbsp;&nbsp;“不会的，我们会用实力证明的。”斯卡兰斯拍了拍伊尔莱丝的肩膀，一只眼里露出了肯定的目光。</p>",
		name = "【风水独眼侠】",
		story1 = 20210125
	},
	[20210126] = {
		dec = "<p>&nbsp;&nbsp;斗智斗勇或许是大家喜闻乐见的戏码，但是只是一味的斗智，会不会产生审美疲劳呢。</p><br/><p>&nbsp;&nbsp;这个问题没有答案，在爱丽丝和奥德莉的争斗之中。作为基金会鲁比克财团的大小姐爱丽丝，在面对天才极客奥德莉的时候，总想要在智慧层面上分出个胜负。毕竟，极客和金融小巨头之间，总有着难分难舍的关系。当佩特里夏进入学院之后，这样的胜负关系就变得更加复杂起来了。</p><br/><p>&nbsp;&nbsp;曾经她们以尼德霍格的一家投资银行的风险处理，作为对赌的舞台。在这家投资银行宣布破产申明的二十四小时前。在检阅完所有的资料后，她们突然间意识到公司的财产评估有着巨大的漏洞。也就是说，一个错误的，或者说计划好的商业决定使得公司举步维艰，这间投资银行大量购买了一种有价证券，但是现在发行这些证券本身变得不值钱了，这即将导致银行的破产。</p><br/><p>&nbsp;&nbsp;发现了这点后，她们对赌谁能想出研究策略来挽救公司。富有经验的爱丽丝决定，银行要以极低的价格抛售这些一文不值的证券。而在意识到背后的连锁反应之后，佩特里夏和奥德莉直接放弃了这次对决。而爱丽丝面对这样的不战而屈人之兵，也索然无味。直接放任了自己的决定。</p><br/><p>&nbsp;&nbsp;而在明面上公司的高层对这些即将到来的金融界的危险既无所畏惧，也不知羞耻。他们在第二天股市一开盘的时候，就抛出所有的不良资产。 这样一来，虽然投资银行能得到暂时的安稳，但却会引发一系列连锁反应，最终厄运还是会降临到这些投资银行的头上。</p><br/><p>&nbsp;&nbsp;这一切，竟然只是三个小女孩之间的赌注。不得不感慨，经济势头瞬息万变好，还是感叹对智力超绝的女孩们，又或是感慨，爱丽丝背后的财团真有钱，能搞出这样的赌局。</p>",
		name = "【智斗巅峰】",
		story1 = 20210126
	},
	[20210127] = {
		dec = "<p>&nbsp;&nbsp;“就算是用这柄勺子，我也能从这个密不透风的空间里脱身出去。你可别小看我爱的意志呢。”</p><br/><p>&nbsp;&nbsp;在一个密不透风的监狱里，有着世界上最严实的看守和监控，你要如何在这里逃出生天。我亲爱的“重刑犯”。也许你听说过用勺子开个秘密通道瞒过狱警，拥抱自由的故事。但是很可惜，这样奇迹的故事并不会在这里上演。因为这样麻烦的事情根本不会被她们所采用，简单粗暴和直接，才是最优的选择。</p><br/><p>&nbsp;&nbsp;如果这个世界在你面前熔铸了一道又一道的铁栅栏，那么最简单的办法，就是拿起手中的电锯，一根又一根地锯开它们。没有什么能够阻止寻爱的少女和执着的信念。如果电锯没有用，那么就用火焰喷枪，如果火焰喷枪也没有用，那么就把这个地方夷为平地吧。</p><br/><p>&nbsp;&nbsp;每个想要困住诺诺和玛姬的监狱，不出意外都难逃被摧毁的厄运。甚至，她们俩不断寻找监狱，摧毁它们。因为这种限制自由的东西，就不该存在。这样的行为，看上去是一种反叛的自由意志。但是，世界上没有了限制，真的会变好吗？</p><br/><p>&nbsp;&nbsp;她们没有能力回答。她们不知道答案。或许这个世界上，真的有答案吗？她们只知道，疯狂的爱恋，才是她们的追求。</p>",
		name = "【失控乐园】",
		story1 = 20210127
	},
	[20210128] = {
		dec = "<p>&nbsp;&nbsp;在奥德莉进入魂器学院的前一年，奥德莉曾负责设计过一个大型连锁超市的网络安全系统。在一次针对人类民用网络的网络电子战中，那家大型超市的系统成了整个地区唯一的幸存者。奥德莉对于这一类普通的委托并没有刻意的进行保密工作，于是这件事被迅速传播开来。奥德莉成了那里的大名人，并在黑客界名声鹊起，慢慢的引起了魂器学院的注意。截止到奥德莉收到学院的录取通知书的那一刻，她已经是一家巨头公司的网络安全顾问了。</p><br/><p>&nbsp;&nbsp;什么时候觉得这个妹妹并不麻烦惹人厌呢？</p><br/><p>&nbsp;&nbsp;大概是才学会站立的她紧抓着我的储存盘不放吧。大概是她坐在旁边看我连夜修缺陷到点着头瞌睡吧。大概是她吱呀吱呀的口齿不清的说着“我，我要和姐姐，一起写，代码马~”大概是站在研究所的废墟上，她紧抓着我的手吧。大概是每天见她的一眼吧。</p><br/><p>&nbsp;&nbsp;什么时候觉得我妹妹是个天才？</p><br/><p>&nbsp;&nbsp;天才总是能第一眼就认出彼此。</p><br/><p>&nbsp;&nbsp;当姐妹俩都出落成人的时候，赛博世界又多了一丝动荡呢。</p>",
		name = "【电驭叛客】",
		story1 = 20210128
	},
	[20210129] = {
		dec = "<p>&nbsp;&nbsp;远坂家与柳生家是世交。远坂秋和柳生薰分别作为远坂家和柳生家的未来家主，很早就相识了。远坂家变故后，远坂秋与柳生家关系虽然变淡，但仍有联系。远坂秋跟随院长学习多年后，回到家乡拜访柳生一族，与柳生薰在道场切磋。柳生薰败给了秋。</p><br/><p>&nbsp;&nbsp;后来，柳笙薰也加入了学院。在秋的眼里，薰一个有天赋，积极学习的后辈，经常对薰倾囊相授。除此之外，薰总是能让秋想起家乡和儿时的时光。这即让秋想靠近又有些害怕</p>",
		name = "【剑道传人】",
		story1 = 20210129
	},
	[20210130] = {
		dec = "<p>&nbsp;&nbsp;布兰琪在擂台生涯中，曾解救过陷入危机的金百莉，从那一刻起，两人的关系便保持在一个十分微妙的地方，朋友之上，恋人之下……只能说二者对对方都有好感，但那份好感要具体用言语来形容的话，却又无法描述……是十分复杂的关系。</p><br/><p>&nbsp;&nbsp;在命运的十字路口，金百莉遇到了布兰琪。那个蔓延着血液和金属气味的地下擂台上，布兰琪为了自己屹立不倒的姿态，无论何时想起来，内心都会涌起一阵暖流……</p>",
		name = "【百合花开】",
		story1 = 20210130
	},
	[20210131] = {
		dec = "<p>&nbsp;&nbsp;有人喜欢光明，追求太阳，这个世界，也允许有人喜欢黑夜，隐藏于暗处。并不是因为对于光明的厌恶，也不是因为对于对黑夜的眷恋。也许她们只是不太善于和人交流，总是在这样的交际关系中一退再退，直到躲身于大家不曾注意的角落。</p><br/><p>&nbsp;&nbsp;她们不喜欢交流吗？答案自然是否定的。她们讨厌说话吗？答案自然也是否定的。</p><br/><p>&nbsp;&nbsp;这个世界上并不存在什么喜欢或者憎恨，也许只有细分下来，才能明白有的是擅长和不擅长的区别。</p><br/><p>&nbsp;&nbsp;幸只是不擅长面对不熟悉的人，她不知道怎样去使用语言来为自己获得更多的社交好感。而萱呢，她只是长期在组织里长大，从来没有人教过她除了暗杀之外的事情，语言对于杀手来说，仿佛是多余的存在。</p><br/><p>&nbsp;&nbsp;没有必要的事情，就没有去做的必要，这个是组织灌注给她的思想。</p><br/><p>&nbsp;&nbsp;现在的萱，就像个婴儿，还在慢慢地学习与这个世界打交道。胧呢，或许也是这样的原因。作为一名洛加尔的忍者，忍道是奉行于世的首要准则。没有多余的动作，没有多余的语言，忍耐长时间的安静环境，这些是她需要去执行的。</p><br/><p>&nbsp;&nbsp;她们是暗夜的行者，是黑夜与死亡的代行者。不是她们喜欢黑暗，而是在漫长的岁月里，没有人给她们带来最炫目最温暖的阳光。</p>",
		name = "【暗夜行者】",
		story1 = 20210131
	},
	[20210132] = {
		dec = "<p>&nbsp;&nbsp;康茨坦丝打开魂器学院医务室的大门，看到随风而过的淡紫色秀发和明晃晃的笑脸。</p><br/><p>&nbsp;&nbsp;“下午好啊，同学你有什么不舒服吗？”那个女孩微笑着说。满室的阳光好像都变得安静，空气里都是笑容的味道。</p><br/><p>&nbsp;&nbsp;此后，康茨坦丝和这个女孩成了搭档。一起打理学生会，一起在医务室帮忙。没有战斗的日子里，生活波澜不惊。一个安静，有责任心的女孩。康茨坦丝这样评价伊文捷琳。</p><br/><p>&nbsp;&nbsp;战斗很快就打响了。战场的惨烈程度远远超出了初出茅庐的小学员们的想象。</p><br/><p>&nbsp;&nbsp;“优先撤退，保存实力！”</p><br/><p>&nbsp;&nbsp;“谁断后啊？”</p><br/><p>&nbsp;&nbsp;“我来断后。”康茨坦丝平静的走出了会议室，盘算着如何为大家争取更多的时间却不料意外的被抓住了衣角。一回头，看见了熟悉的淡紫色长发和满是担忧的眸子。</p><br/><p>&nbsp;&nbsp;“没事的，我会保护每一个人的。”康茨坦丝安抚的拍了拍伊文捷琳的手。</p><br/><p>&nbsp;&nbsp;之后，便是没什么新意的故事。进攻的人工智能，震天的炮火，这一切和学院的生活像是两个完全不同的世界。大家撤退的如何了呢……康茨坦丝想着。坚持到现在可以了吧……好累啊……，没想到稍有松懈，一只不曾注意到的人工智能从侧面猛扑过来。</p><br/><p>&nbsp;&nbsp;此刻，突然有个淡紫色的身影破空而出，带着坚毅与决绝：“我会救治每一个人，也绝不会放弃你！”</p><br/><p>&nbsp;&nbsp;在听闻了她们的故事之后，妮妮珐不知道出于什么原因竟然也加入了救治学员们的一线。也许，她只是为了更加方便进行她的采血实验，也许，也是被伊文捷琳和康茨坦丝的真情所打动了。</p>",
		name = "【医护先锋】",
		story1 = 20210132
	},
	[20210133] = {
		dec = "<p>&nbsp;&nbsp;琉璃来自于一个洛加尔音乐氛围浓厚的家庭。父亲地下乐队队长，母亲是音乐教师。琉璃的父母毕业于同一家艺术学院。而两人相爱的历程也是教科书式的欢喜冤家展开——入学那天，琉璃妈妈提着小提琴听着莫扎特撞到提着鼓棒留着长发听着摇滚的琉璃爸爸怀里的那一刻，就注定了这二人必然有不寻常的展开。</p><br/><p>&nbsp;&nbsp;于是二人就从入学吵到了毕业，然后再从毕业吵到了结婚典礼。在之后，那就是琉璃出生之后的事了。在父母的熏陶下，琉璃热爱音乐，从小接触各种乐器，尤其爱唱歌。少儿时期常常拿到儿童歌唱比赛的第一名，是小有名气的儿童歌手。如果没遇到那一场意外，琉璃可能走上父母们的道路，去上音乐学校，未来可能成为一名音乐老师。</p><br/><p>&nbsp;&nbsp;在一次旅行途中，琉璃和家人所在的城市被人工智能突袭，当地居民死伤惨重。琉璃和家人在地下的避难所避难。避难所里的人们，蜷缩在一起瑟瑟发抖，黑夜漫长而寒冷。</p><br/><p>&nbsp;&nbsp;不知是谁，开口唱了第一句，撕裂开了避难所里绝望的空气。越来越多的人参与进来，希望重新燃起。小小的孩子还不会说话，咿呀半天，吐出了几个调调。母亲终于哭出声音来了，一边哭一边跟着唱着摇篮曲。</p><br/><p>&nbsp;&nbsp;琉璃看着这一幕泪流满面。在语言和文字还未降临的时代，人们是靠着音乐来约定的吧。琉璃跟着哼了起来，在场的人们也都哼了起来，我们尚且平安。</p><br/><p>&nbsp;&nbsp;在那之后，琉璃决定把守护和希望通过歌唱带到世界的每个角落。于是，琉璃出道成为偶像，现在也在为成为顶级歌姬而努力着！和夏洛特结识之后，琉璃常和夏洛特一起探讨音乐。渐渐的夏洛特萌生了组一个摇滚乐队的想法，琉璃也想尝试新的风格，两人一拍即合。随机组了一个摇滚小乐队，琉璃担任主唱。</p><br/><p>&nbsp;&nbsp;她们相信，音乐能够为大家带来最明亮的明天。</p>",
		name = "【明日旋律】",
		story1 = 20210133
	},
	[20210134] = {
		dec = "<p>&nbsp;&nbsp;大海航行靠舵手。这次我们就讲述一个关于航海水手的故事。</p><br/><p>&nbsp;&nbsp;每个对海洋情有独钟的人，都能对她们所喜欢的海洋说出个一二三来。有的人，毕生都在追求一个神秘的、巨大的海底生物，把它视作上帝的救赎，也把它视作复仇的对象；也有的人，出海追寻一个朋友，一个坚守的理由；也有的人，不仅是对海面的迷恋，而是更钟爱海洋的深度，探究秘密的更深维度；甚至还有的人，生在海里，却向往着海之外的生活。</p><br/><p>&nbsp;&nbsp;有的秘密沉没在海里，有的传说就活在看不见的海里，财富、名望、传说、恐怖和未知，她就是这样一个多面的、充满魅力的少女。她们就像是为海而生的孩子们，希艾姆喜欢海，也喜欢征服她。喜欢躺在沙滩边上感受海浪的波纹，也喜欢征服她层层的桀骜不驯。喜欢她供给世界的一切奇珍异物，也喜欢掠夺她私藏的宝藏。</p><br/><p>&nbsp;&nbsp;卡翠欧娜喜欢大海，就表现得很简单也很单纯。她喜欢被海洋包裹的感觉，喜欢她和蓝天相接的浑然一体。卡翠欧娜和大海更像是一对要好的朋友，从不争执，顺其自然。她可以告诉她所有的心事，她也会做一个忠实的听众，默默承受着这一切。卡翠欧娜就像海的女儿一样，温柔娴静。</p><br/><p>&nbsp;&nbsp;而斯卡兰斯对于海的感情，就复杂很多。她接受海的馈赠，她因为海的变化而变化，她的生活就像海上的波澜一样，有起也有落。如果说卡翠欧娜是被海怜爱的掌上明珠，那么斯卡兰斯更像是大海本身的波浪，她们休戚与共息息相关。</p><br/><p>&nbsp;&nbsp;当水手们想要征服大海的时候，会发生什么有趣的事呢。那些事，也一定是能够被传颂的佳话吧。</p>",
		name = "【水手】",
		story1 = 20210134
	},
	[20210135] = {
		dec = "<p>&nbsp;&nbsp;游戏厅里的制霸之王，人人闻风丧胆的小埋军团军团，今天也如往常一样开始制霸游戏厅内所有的游戏。新款式的喵郎玩偶也一定在她们的计划之中。一如往常，希尔芬小姐也把小埋当作她夺冠的最大障碍，向她发起了挑战。</p><br/><p>&nbsp;&nbsp;这场战斗将通过猜拳决出胜负，而这场战斗还有个意外的来客——海老名，小埋隐隐感到朝向胜利的道路上有些困难和阻碍。这场简单的猜拳对决，看来还有很多变数，小埋对的得意弟子切绘也决定在这场出道战中，向师父证明自己的实力。</p><br/><p>&nbsp;&nbsp;一场电子游戏厅的光影对决即将拉开序幕。</p><br/><p>&nbsp;&nbsp;眼看这场没有硝烟的战争就要打响，但是谁能想到明天和意外总是争着抢着来到大家的面前。</p><br/><p>&nbsp;&nbsp;也不知道哪里冒出来的小喽啰们，竟然打算和小埋军团军团抢占这个游戏厅。他们叫嚣着、嚷嚷着说什么制霸世界的每一个游戏厅，成为真正的游戏厅之王。这些不知天高地厚的小家伙们，殊不知他们在对着谁、什么人说着这样狂妄的话语。他们竟然还派出了射击游戏天王、格斗游戏天王、棋牌游戏天王、钓鱼游戏天王、横版过关游戏天王这“四”天王来叫阵。</p><br/><p>&nbsp;&nbsp;也许，小埋军团军团有着日常的小打小闹，但是，在面对共同敌人的时候，那么吃亏的可就是对方了。</p><br/><p>&nbsp;&nbsp;守护秘密基地游戏厅，小埋军团军团出动！</p>",
		name = "【小埋军团】",
		story1 = 20210135
	},
	[20210136] = {
		dec = "<p>&nbsp;&nbsp;西奥多博士，一个理想主义的偏执科学家。曾经在军方的招募下，配合卡莱克尔军方进行了杰格计划以及变式血清强化人计划。在着手进行血清研究的时候，西奥多博士陷入了自己的偏执和死胡同。由于后期实验的失败和内容泄露造成的舆论问题，军方不得不中止和暂停了西奥多博士后续的研究。西奥多博士因为这次事件，虽然没有被军方剔除出来，但是他自己却在私底下继续血清的实验研究。</p><br/><p>&nbsp;&nbsp;一段时间后，军方得到了上层的技术援助，开始了一项新的计划实验，西奥多博士再次被重新调用，参与了本次秘密实验。这是西奥多博士第一次接触到了《逝物录》的内容。这也是西奥多博士在离开军方后，脊髓神经连接型动物性拟态外骨骼系统的灵感来源。</p><br/><p>&nbsp;&nbsp;塞尔凯特、艾度斐度、埃希诺她们原本都是战争的孤儿，西奥多博士在离开军方之后，出于复杂的原因救济和抚养了她们。她们在西奥多博士的培养之下，享受到了之前从未有过的家庭的温暖，她们对博士也有着复杂的情感。她们目睹了博士的困境、瓶颈还有内心的煎熬，也目睹了人工智能的暴烈、博士的焦躁以及科学家的一种疯狂。</p><br/><p>&nbsp;&nbsp;她们偷偷参阅了博士的研究计划，明白了博士的设计蓝图能够成功，还差实体实验。而使用实体实验就会涉及到道德的灰色地带。博士的煎熬和犹豫正是在此。为了解决养父的烦恼，她们决定让博士在自己身上进行尝试。当她们和博士表露心意了之后，博士愤怒地呵斥了她们。在漫长的内心煎熬之下，博士最终还是接受了孩子们的提议。</p><br/><p>&nbsp;&nbsp;拟态的外接初次实验非常成功，博士和孩子们都非常开心。但是，这只是开始，之后还有更多的困难在等待着他们……</p>",
		name = "【仿生科技】",
		story1 = 20210136
	},
	[20210137] = {
		dec = "<p>&nbsp;&nbsp;味觉，是比思乡之情涌上心头更容易唤起乡思的感觉。</p><p>&nbsp;&nbsp;迷失在霓虹森林里，有时候，节日的氛围已经和这些红蓝、红紫或是蓝紫的氖光灯混为一体，仿佛每一天都是节日，也好像每一天都不是节日。传统仿佛已经被高速发展的赛博狂欢给远远地甩在了后面，如果每天都是狂欢节，那么谁还会去期待关于过去的庆祝呢。但是，舌头是不会骗人的，味觉的记忆也是不会骗人的。有些食物、有些料理，就是牢牢地和节日记忆联结在一起。</p><p>&nbsp;&nbsp;也有很多食物，是在漫长的岁月里，不断被历史、被文化给赋格、给建构。原本仅仅是作为果腹食粮的它们，被时代文化包装成了与节气息息相关的一部分。巧克力成为了传递甜蜜的使者，情侣之间的轻言蜜语、羞于表达的情愫，成为这个带点苦涩的食物的使命。榛子巧克力成为了忠贞的代表，果仁巧克力则成为可人的发言，而充满奶香的巧克力，则是告诉对方，你是我的甜蜜这样的暗语。饱含情感和记忆的故事，是让月饼、汤圆成为时节代表的重要原因。她们除了是心意的传达意外，更重要的是历史传承。无论是掐甜入馅，还是攒咸藏鲜，都是每个人最独特的回忆。食物，并不是为了果腹，更多的是入口那一刻温暖的守候。</p><p>&nbsp;&nbsp;她们通过风味筑起了时节的记忆，牵动了每一个异乡游子的心绪。天南海北，也许家人不能长相伴，行路迢迢，也许佳人不能长相依，但唯有美食，一路相随，抚慰辘辘饥肠，温暖人生况味。</p><p>&nbsp;&nbsp;但是，玉子烧、巧克力、汤圆和月饼，甚至更多的时节岁友来到学院，就是来学习交流的，你可不要为了吃而缠着她们呀~！</p>",
		name = "【时节岁友】",
		story1 = 20210137
	},
	[20210138] = {
		dec = "<p>&nbsp;&nbsp;直拳，闪躲，勾拳，防御，击倒。</p><p>&nbsp;&nbsp;汗臭味，湿漉漉的毛巾，呐喊声，小动作，嘘声，鼻血甚至身体疼痛和晕眩。6米见方的拳击台，如此令人着迷，好像只有不断击倒对手，才能证明自己存在的价值和强大。好像只有肾上腺素迸发，呼吸急促、大汗淋漓似乎才是活着的感觉。这样昏天黑地、没日没夜的方寸上的拼搏，什么时候才是尽头。布兰琪自己也不知道。谁也不知道。这些人都赢不过自己，这些人都不是暗算父亲的人。但是他们为什么都笑得这么开心，喊得那么卖力，都这么喜欢看到被击倒者的不幸、疼痛和悲伤吗。</p><p>&nbsp;&nbsp;我这样一直赢下去，是不是给经纪人赚了很多钱了。啊，我都快要忘记了，我就一个人。像我这样没有经纪人，不打黑拳，是不是断了很多人的财路。一窍不通，难怪父亲也曾说我，这个牛脾气，就是犟。现在呢，啊，真希望能够再听一次父亲的声音啊。</p><p>&nbsp;&nbsp;都是你们这些家伙，都是你们这些家伙，都是你们这些家伙！</p><p>&nbsp;&nbsp;你们全部都是害死父亲的凶手！不可饶恕！就让你们尝尝拳头的滋味。</p><p>&nbsp;&nbsp;如果被仇恨蒙住了眼镜，其他的感觉就会变得更加灵敏。</p><p>&nbsp;&nbsp;就没有人能打倒我。</p><p>&nbsp;&nbsp;我就能够打到生命之火燃尽。</p><p>&nbsp;&nbsp;就这样好吗，不断的挥拳，格挡，挥拳，格挡，闪躲，挥拳。</p><p>&nbsp;&nbsp;我是不败的神话，哈哈哈哈哈哈。</p><p>&nbsp;&nbsp;直到地下拳王碰到金色的光……“汝，就是不败的拳皇吗？就让妾身来会会你~“命运的转轮，就开始变得不同……</p>",
		name = "【拳霸之路】",
		story1 = 20210138
	},
	[20210139] = {
		dec = "<p>&nbsp;&nbsp;在很久以前，旧时代每四年就会有一次盛大的、全世界运动迷们疯狂的竞技比赛。随着时代的落幕，很多事情都需要和我们告别。自然这场盛大的全球活动也告别了我们。</p><p>&nbsp;&nbsp;这不，为了跟上现在复古的时尚潮流，学院复刻了一下这个传说中的比赛。也许，只是年终为了报销经费的由头。谁知道呢。</p><p>&nbsp;&nbsp;搭建了看台，组织了成员参赛，空出了大场地，就是为了迎接这个大家都跃跃欲试的比赛。日露霞表示离开军方之后，已经很久没有见到过这么大的阵仗了。以前只有在军方检阅军队、军备情况的时候，才能看到乌泱泱的人。日露霞表示她竟然有点兴奋起来了，但是现在有点体温过热，不得不先去医疗室报道检查一下。如果有什么比赛的话，霞也想参加。她能够打倒一片。说到打倒一片，日露霞是不是理解错了什么，体育竞技不是斗兽场决斗。但愿她想明白了。</p><p>&nbsp;&nbsp;妮可尔想要在这次的比赛中组织一次场球赛，可是也找不着11个队员。没过多久，“绝杀”队就这样提前在决赛前迎来结束。不过就算组成了，她们貌似也没有对手，可以宣布直接夺冠了。所以，妮可尔就和李开始了兜售黄奶茶的旅程。</p><p>&nbsp;&nbsp;为什么兜售黄奶茶？自然大家都很想知道，而李回答自然是很简单，“谁看世○杯不来点黄奶茶瓜子或者饮料呢？”道理大家都懂，但难道不应该是啤奶茶吗？也许，这样也是黄奶茶生产股价上涨的原因之一。",
		name = "【学院杯】",
		story1 = 20210139
	},
	[20210140] = {
		dec = "<p>&nbsp;&nbsp;野外生存训练，是魂器学院每年冬天都会开展的活动。它能够充分锻炼学员们的体力、意志力、动手能力以及判断力，这些对执行任务来说都是必须的。所以，每年的训练，学院都要求所有学员参加，她们需要在寒冷北欧的一处荒岛，经历长达一周的荒野求生。另外，今年的训练还增加了额外规则——在正式开始前，学院将用抽签的方式对学员们进行分组，这对学员们的团队协调能力也是一次极大的考验。</p><p>&nbsp;&nbsp;临时分组，加上寒冬的天气，让今年的野外生存训练变得格外艰难。学员中有半数小队在训练开始第三天就主动放弃，而到了最后一日，还在坚持的队伍只剩下了七支不到。</p><p>&nbsp;&nbsp;训练结束、学院进行学员们的回收作业时，那些坚持到第七天的学员们无一不是蓬头垢面、无精打采，无论是体力还是精神都已到达极限——除了一个小队之外。在训练组老师在荒岛的雪地里发现奥德莉、皮卡、芭荼荼以及艾瑞儿时，她们正在一辆废弃的房车里烤着电暖炉，一边等着电烤箱里的海鲈鱼成熟，一边通过车载终端玩着网络游戏。这让在场的所有老师都大跌眼镜。</p><p>&nbsp;&nbsp;原来，在训练开始之前，奥德莉就离线保存好了荒岛的卫星图，高达 10TB 的地图数据甚至能够显示荒岛上的每一处兔子洞，更别说遗弃的道具或设备；接着，皮卡与芭荼荼利用她们电磁系魂武的能力，给废弃房车里的设备通上了电；而同组的艾瑞儿，则有更加神奇的、随时随地联网的能力……于是，在奥德莉花半小时修好了车载终端之后，四名女孩就过上了钓鱼、睡觉、玩游戏的悠闲生活——与其说这是野外生存，不如说是北国度假。</p><p>&nbsp;&nbsp;最后，学院判定奥德莉、皮卡、芭荼荼与艾瑞儿四名学员没有任何作弊，并且在野外生存的最后一天保持了最好的状态，为她们颁上了“生存标兵”大奖。",
		name = "【电磁妙用】",
		story1 = 20210140
	},
	[20210141] = {
		dec = "<p>&nbsp;&nbsp;缇法、珍妮特、千竹与雾夜的小队，是最让魂器学院的射击老师省心的一支小队。她们四人有着绝佳的射击天赋，且都十分热衷于学习和训练，截止到黑街的武器商缇法入队，与她一同到来的还有黑街有关枪械的构造与养护知识，老师们已经没有什么可以传授给她们的了。每日的自主训练，都是为了保持射手的敏锐状态，再无进阶的课程可以研究。</p><p>&nbsp;&nbsp;为了不让学员感到飘飘然、从而荒废自己的天赋，布克丝院长提出了一个全新的训练模式，让四位学员调换武器——缇法使用珍妮特的光束步枪，雾夜使用千竹的狙击枪，千竹与珍妮特使用双突击步枪，以这样的搭配来进行训练。这让四位学员顿时慌了阵脚，在最开始的模拟战训练中，千竹与珍妮特因为不熟悉突击步枪的射程，命中率下降为以往成绩的两成；而另一边，缇法与雾夜则对长距离步枪的机动性与连发性能抱怨不已，迅速被应接不暇的敌人淹没。</p><p>&nbsp;&nbsp;可是，四位学员并没有受到打击，反而立即明白了新模式训练的用意。如今，只要不是上课时间，四位学员就一直呆在一起，讨论着彼此武器的性能与使用技巧。尽管长期的习惯让她们的训练进展不是那么快，但四人的成绩仍在稳步提升中——这让我们相信，不久后，一支能够使用各种枪械、应对所有作战情况的全能“枪神”小队，就会诞生在魂器学院。",
		name = "【神枪萝莉】",
		story1 = 20210141
	},
	[20210142] = {
		dec = "<p>&nbsp;&nbsp;同样来自忍者氏族的铃兰与胧，家族的命运是截然不同的。</p><p>&nbsp;&nbsp;风魔家与世无争，固守着忍者的传统，在和平的时代渐渐隐退，如今仅剩胧的家庭一支；而刃隐家则完全相反，他们积极地接纳现代科技，在热兵器的时代也不停地壮大着，防弹衣、夜视仪、电磁武器，诸如此类的先进装备装配到忍者身上时，让他们成为了真正意义上的“超级刺客”，活跃在世界的暗面，如今刃隐家是一个有上千人的巨大家族，当代第一忍者世家，也是这个世界最令人闻风丧胆的组织之一。</p><p>&nbsp;&nbsp;作为刃隐家家主的千金，背负着家族的使命，铃兰自幼便受到严苛的训练，并有着与同龄人不同的冷静与成熟。而胧则显得更加单纯，一直以洛加尔传统方式生活的她来到学院以后，享受到了许多新鲜的体验。尽管二人的“忍道”不尽相同，但她们是乐意与对方协作的好搭档。激进与保守，先进与传统，二人合作中创造出了许多次惊人的成绩；她们在学院里也相互较量，共同成长，如今是最值得信任的小队之一。</p>",
		name = "【忍途双花】",
		story1 = 20210142
	},
	[20210143] = {
		dec = "<p>&nbsp;&nbsp;拉比特与碧萝丝，是一对来自耶梦加得的姐妹。虽然没有血缘关系，但在同一个福利院长大的她们，关系要比一般的亲姐妹好很多。她们有着同样的兴趣爱好，并且都将它当做了自己的事业——那就是涂鸦。在耶梦加得的街头，你时常能看到一些充满个性的涂鸦，有的是动物，有的是人物，也可能是文字，它们是那样耀眼，犹如这座城市的名片，总有许多慕名而来的人在涂鸦旁合影。它们都是出自拉比特与碧萝丝之手，如今二人也是国际上相当有知名度的涂鸦艺术家。</p><p>&nbsp;&nbsp;来到了魂器学院之后，拉比特与碧萝丝也在不停施展着自己的才能。最著名的一次事迹是，两人在学院泳池维护的一天晚上，在泳池内壁上进行了创作，珊瑚、热带鱼、螃蟹、鲸鱼、水母，还有骇人的大鲨鱼，拉比特与碧萝丝就像施展魔法一般，把学院的泳池变成了海底世界，让所有的同学都惊叫不已。</p><p>&nbsp;&nbsp;然而，尽管很可爱，但如此耀眼的色彩会对学员水下的训练形成干扰，学院不得不命令拉比特与碧萝丝将涂鸦清除——于是，在那之后的两天傍晚，都能看见两人使用刷子在泳池奋力清扫的模样。备注：友好的同学们随后加入了清扫大军，整个清扫工作从原本预估的一个月缩短为了一周。",
		name = "【空想色彩】",
		story1 = 20210143
	},
	[20210144] = {
		dec = "<p>&nbsp; &nbsp;同样在执行任务时充当“猎人”的萨姬塔、艾玛、萱，在购物时面对琳琅满目的商品亦是天生的猎手。无论是型号众多分不清色彩的口红，还是样式多样版型众多的新衣，三人总是能够在其中挑选出最适合自己的那一件。这大概就是“猎手的直觉”？<br/></p><p>&nbsp; &nbsp;在购物方面，三人不仅眼光独到，还共同有着酷爱囤货的癖好。也正因为这个特性，魂器学院的学员们在逛街时常常避开她们——商品都被她们买光了！霓昂猜疑她们这种控制不住囤货欲望可能来自曾经生活的贫瘠，苦难常常在人的身上留下伤痕——无论是物理上还是精神层面上。<br/></p><p> &nbsp; &nbsp;但是这样不受控制的购物欲也带来了许多麻烦，许多商品还没有使用就已经超过保质期了，这种大量的物资浪费引起了布克丝院长的不满。三人一边被霓昂带走教育，一边不得已冻结了大部分个人资金。如果霓昂的思想教育是在是改变不了她们的话，她们没钱也是没法购物的吧？哎……</p>",
		name = "【天生猎人】",
		story1 = 20210144
	},
	[20210145] = {
		dec = "<p>&nbsp; &nbsp;刻罗和爱丽丝、索菲亚是久交的老友，最早可以追溯到爱丽丝五岁的时候。刻罗清晰的记得那时爱丽丝还很娇小虚弱，可是智商却已经碾压成年人，索菲亚作为鲁比克集团的特聘机械顾问，陪着爱丽丝前往赌马场消遣娱乐。<br/></p><p> &nbsp; &nbsp;她当时比这两人都为年长，在一圈大人中看见两个未成年的到来属实奇怪，她不由自主将目光落在两人身上，直到这份好奇在爱丽丝连续赌马成功后变成了惊讶和欣赏。</p><p> &nbsp; &nbsp;刻罗大概那时骨子里就不是一个守规矩的人，她毫不犹豫在索菲亚疑惑的目光下将她们请到品茶包间，直言要与她们结交朋友。</p><p> &nbsp; &nbsp; 后来在无数个名流宴会上，一些贵族世家子弟看到爱丽丝索菲亚与刻罗相聚一起侃侃而谈，不由觉得这世界的奇妙，三个年龄差距这么大又除了家族毫无相关的人，竟也成了彼此的至交好友。<br/></p>",
		name = "【鲁比克三巨头】",
		story1 = 20210145
	},
	[20210146] = {
		dec = "<p> &nbsp; &nbsp;当一群精神病人聚集在一起会发生什么呢？答案是她们会互相聊天聊得津津有味，甚至差点互相引以为知己。没错，就是这么没有逻辑，让人啼笑皆非的展开！</p><p>&nbsp; &nbsp;当薇薇恩，拉普拉斯，安娜，艾丝翠德四人在班长召开的夏日祭晚会上莫名其妙聚在一起后，属于精神病人们的茶话会开始了！</p><p>&nbsp; 据那天唯一观看了整场茶话会的普通路人卡米拉所说，现场氛围意外的和谐，尽管她们彼此聊天的话题驴头不对马嘴，全员跨服聊天，但意外的事每个人独立的话题却能彼此无缝衔接，这大概……就是属于精神病人的磁场？</p><p>&nbsp; &nbsp;不要思考……去感受。</p>",
		name = "【思维病变】",
		story1 = 20210146
	},
	[20210147] = {
		dec = "<p>&nbsp; &nbsp;蒙蒂尼家族的落幕犹如落日余晖，虽繁华已尽，但仍有余力。可以说是瘦死的骆驼比马大，至少目前而言，蒙蒂尼家族的剩余家产仍有可能支持金百莉东山再起，当然，这是在家族内人心不散，外部无施压的情况下。</p><p>&nbsp; &nbsp;对于金百莉来说，复兴家族是头等要事，身为贵族便应该有贵族的骄傲，以家族存亡为己任，担负起属于自己的责任。</p><p>&nbsp; &nbsp;但是对于那个离经叛道的二小姐来说，……大概她连家族里有几支人脉都已经忘光了吧！在奈儿眼中，那些零零落落的家族余力毫无吸引力，对复兴家族重现威光更是嗤之以鼻，甚至对于姐姐的忙碌奔走的行为多次反对。</p><p>&nbsp; &nbsp;既然已经我方唱罢，何必还要再次登场？不如将此事抛却脑后快意余生，顺应天命罢了！</p>",
		name = "【落日余晖】",
		story1 = 20210147
	},
	[20210148] = {
		dec = "<p>&nbsp; &nbsp; 艾，凯拉，那须野红叶，伊卡洛维在同是异化人的小团队中，非常能够放得开。</p><p>&nbsp; &nbsp; 因为都带有动物体征的缘故，彼此经常聚在一起吵吵闹闹互相撸毛。特别是对于毛发旺盛的犬系动物来说，抚摸身体和头部简直是表示亲近的最好方式。艾在异化人小团队中，俨然是领导者的架势，虽然她很希望让这个“异化人联盟”正经起来，不要每次聚会都打成一片闹腾不休，可是这怎么可能成功呢？</p><p>&nbsp; &nbsp; 携带着动物爱动贪玩基因的她们，基本每次都会酣畅淋漓地打上一场，随后再各自拱在一起呼呼大睡，让艾有时看着被这群多动症拆掉的家具，真的很想问你们都是哈士奇吗？？每次事后看见她们“我是错了，但下次还敢”的样子，她真的很想给她们一掌……</p>",
		name = "【异化人联盟】",
		story1 = 20210148
	},
	[20210149] = {
		dec = "<p>&nbsp; &nbsp;对于教育水平不同的人来说，接受过相同教育的人价值观人生观更容易一致，在聊天聚会时更容易聚在一起。克妮雅、织夜、妮妙和刻罗正是如此。</p><p>&nbsp; &nbsp;她们四人都是接受的精英主义教育，总是在学院举办的各个聚会中不知不觉就聊到了一起。在畅谈经济，文化和各自擅长领域四人都各有见解。即使对待同一问题产生了争执，良好的教养也让她们能够及时地化解不快，或是通过幽默风趣的玩笑话轻轻揭过去。</p><p>&nbsp; &nbsp;有时候她们的聊天更像是吐槽大会，最多的就是对自家严厉的父母的吐槽：堆满空闲时间的家教课，繁多复杂的礼仪文化，强制灌输的各种无聊的知识，哎，实在是令年少时的自己痛苦万分。当然，众人不得不承认，如果没有这种痛苦的精英主义教育，也不会有今日优秀的自己了。</p>",
		name = "【精英主义】",
		story1 = 20210149
	},
	[20210150] = {
		dec = "<p>&nbsp; &nbsp; 所谓不打不相识，瑟坦达一来到魂器学院，便总是想要与学院内部的武术家们切磋一番。摸清楚学员们各自的情况后，很快将目标锁定在了 麟和黑木幸身上。一个派森系武术大家，一个洛加尔系武技高手，如果能与她们二人切磋武艺，互相喂招磨练，想必自身的武术会精进许多吧！</p><p>&nbsp; &nbsp; 然而事情的发展并非瑟坦达所想。首先是不走寻常路的麟，麟的武艺千变万化难以捉摸就不说了，关键是她的招式时常是她一时兴起即时创作而成，体系流派是一点没有，让瑟坦达一时不知如何应对学习，不过这也让她学会了武术学习不可拘泥于形式这个道理。</p><p>&nbsp; &nbsp; 至于面对黑木幸的日式剑术，惯常使枪的瑟坦达十分不习惯接她的招，她也无法理解黑木幸口中的“一元斩”，总觉得这是形式大于实际的东西，何况在战场上，剑真的会比长枪好用么？</p>",
		name = "【诸武精通】",
		story1 = 20210150
	},
	[20210151] = {
		dec = "<p>&nbsp; &nbsp; 属于托拉的故事是个很漫长的故事。这个故事始于一只小狐狸荒唐的猜想，却逐渐演变为一个智慧的长辈对传统文化的坚守。</p><p>&nbsp; &nbsp; 人类科技经过技术爆炸在短暂的数十年内进步到全面信息时代，与科技发展相对的是传统文化的大量丢失。那些浩如烟海的人类文化典籍和数不清的人类文明遗址被这个时代的人们毫不留情地抛弃，毕竟比起枯燥无味的传统文化，现代世界的电子科技更加引人侧目。</p><p>&nbsp; &nbsp; 然而无论什么时代都不缺逆行者，托拉组织便是这么一群固执地坚守传统文明的“守旧派”。托拉始终认为，无论时代如何变化，人类都不可以丢失属于自己的历史文化，因为在浩瀚的宇宙中，渺小的人类想留下痕迹的唯一方法，便是保存下人类自己的文明记录。</p>",
		name = "【托拉的意志】",
		story1 = 20210151
	},
	[20210152] = {
		dec = "<p>&nbsp; &nbsp; 时间白驹过隙，也许安提帕斯家族早就忘记了那个名为约翰的“男孩”，也许萨洛弥也早就遗忘了年幼时“哥哥妹妹&quot;的相依相伴，如今独守着这些美好回忆的，也只有蕾塔一人。</p><p>&nbsp; &nbsp; 萨洛弥和蕾塔过去那被人逐渐抹平的故事，犹如王尔德戏剧中的《莎乐美》一般，充满了“爱”与“美”、“爱”与“罪”。对于萨洛弥来说，自己的长姐是个过于勤勉和有些“奇怪”的大人。日复一日的刻苦训练，张口闭口都是“不能让父亲失望”，让萨洛弥只敢远观，难以生出亲近之意。</p><p>&nbsp; &nbsp; 对于蕾塔来说，萨洛弥这个家族的小女儿，她的幼妹，在她眼中永远是与“需要人保护”、“需要人疼爱”、“弱小无助可怜可爱”等词汇相关，这大概是蕾塔的眼睛自带了八百米滤镜，不然明明萨洛弥才更像是欺负别人的那一个，在蕾塔口中怎么就是“需要爱怜的玫瑰花”了。</p>",
		name = "【莎乐美】",
		story1 = 20210152
	},
	[20210153] = {
		dec = "<p>&nbsp; &nbsp; 众所周知，在学院里有这么两个共识：一是蛟和啸几乎时时形影不离。二人永远互相陪伴，相互牵挂，是彼此不可分离的家人。如果两人暂时不在一起，想要找其中一个人，只需要问另一个人就好了。</p><p>&nbsp; &nbsp; 二是宁愿惹啸生气，也不可以惹蛟生气。因为啸生气了一般只用老老实实被啸打一顿就好了，而如果惹蛟生气的话……别看蛟柔柔弱弱，很多人被她坑的时候还替她数钱呢！不仅如此，事后还会迎来啸的“正义修正铁拳”。</p><p>&nbsp; &nbsp; 蛟和啸由于突然被从基金会送到魂器学院，人生地不熟的时常会感到有些不适应，但是在班长的爱心看护下，渐渐放下了对学院的防备，现在也渐渐开始尝试与学员们交流玩乐了。用班长的话说，蛟和啸是很缺安全感的孩子，希望大家包容她们吧~</p>",
		name = "【家人】",
		story1 = 20210153
	},
	[20210154] = {
		dec = "<p>&nbsp; &nbsp; 小孩子的世界总是充满着天马行空的幻想与“很不合理”的逻辑理念，在魂器学院的孩子们往往经历更多，思想更加“千奇百怪”。</p><p>&nbsp; &nbsp; 比如在一众孩子们中看上去还比较靠谱的千竹，也会在看着团子进食时突发奇想自己能不能吃竹子，结果差点咬坏了刚换的牙。总是迷迷糊糊的伦茨，间歇性会幻想自己是一个不停旋转的小陀螺，然后在屋子里转来转去撞来撞去，把自己给转的头晕眼花。</p><p>&nbsp; &nbsp; 艾莉卡最近迷上了猫薄荷，总觉得这玩意泡茶也许会别具风味……？一直只和歌德沟通的露缇倒是和新来的诺比意外玩到了一起去，虽然二人总是跨服聊天，说话你一句我一句驴头不对马嘴，但最终都会奇妙地十分赞同对方的想法，可能……这就是孩子们特殊的沟通技能吧?",
		name = "【孩子的世界】",
		story1 = 20210154
	},
	[20210155] = {
		dec = "<p>&nbsp; &nbsp; “她逃，她追，她们都插翅难飞！”</p><p>&nbsp; &nbsp; 藤原蝶和阿亚斯是学院内公认的一对欢喜冤家，有她们出现的地方就有各种“欢声笑语”和“无厘头事件”的出现。藤原蝶来自重规矩的世家寒门，而阿亚斯是个标准的风流纨绔，二人一冰一伙，每每撞见总是惹出一些令人啼笑皆非的故事。</p><p>&nbsp; &nbsp; 据阿亚斯本人所言，美丽的藤原蝶小姐是她命中的公主，是那么美丽、纯洁、善良（此处省略500字）……第一次见到她就俘获了自己的心。但落花无情，流水有意，藤原蝶只觉得不靠谱的阿亚斯一点也不持重守礼，丝毫没有礼仪教养，张口闭口就是擅自给自己起的昵称“小蝴蝶”，难道她们俩很熟吗？哼！</p>",
		name = "【欢喜冤家】",
		story1 = 20210155
	},
	[20210156] = {
		dec = "<p>&nbsp; &nbsp; 佩尔与萨洛弥的结识起始于一次文艺汇演。那时的萨洛弥刚刚喷上最新研制的“幽蓝玫瑰”香水，在舞台上结束了一支拉丁舞，本以为能够获得班长全部赞扬的萨洛弥没想到下台时听到班长说了一句“萨洛弥的拉丁舞真是艳惊四座啊，舞蹈的力量真是迷人，我开始期待佩尔表演的芭蕾了！”</p><p>&nbsp; &nbsp; 这句话可激起了萨洛弥的好胜心，难道还有别人的舞蹈比自己更加美丽动人吗？直到帷幕打开，如月色般的灯光照耀在佩尔白皙的面容上，女孩穿着天鹅舞裙翩翩起舞，修长笔直的小腿和小巧的足尖高高抬起，时间仿佛在这一刻停止了。</p><p>&nbsp; &nbsp; 等到佩尔一舞结束，萨洛弥仿佛才从那如梦似幻的美妙舞蹈中回过神来，心中不禁暗暗纳罕：原来这世上的舞蹈各有千秋啊。</p>",
		name = "【舞蹈家】",
		story1 = 20210156
	},
	[20210157] = {
		dec = "<p>&nbsp; &nbsp;同为“遗弃者”，也同样怀有着一颗正义之心，莱拉向往着成为某人的守护者，成为仅属于她一人的骑士，而虹则梦想着成为行侠仗义，来去如风的大侠。</p><p>&nbsp; &nbsp; 两人虽然珍惜彼此，但无论如何也无法放弃自己的追求，因此最终两人踏上了不同的道路。</p><p>&nbsp; &nbsp; 时至今日，两人的道路竟在机缘巧合之下再度交汇于魂器学院，以不同的方式一路走来的两人，她们彼此的意志又会摩擦出怎样的火花呢？</p>",
		name = "【骑士与侠客】",
		story1 = 20210157
	},
	[20210158] = {
		dec = "<p>&nbsp; &nbsp;刃隐遥与刃隐铃兰并非亲生的姐妹，却有着超乎亲生姐妹的浓厚感情（虽然只有刃隐遥自己这么认为）。对于刃隐铃兰而言，刃隐遥其实就像刃隐家族的其他成员一样，她对家族中的每个人都一视同仁。而对于刃隐遥而言，刃隐铃兰是拯救了自己的救命恩人，是自己值得奉上生命去追随的“姐姐大人”。而当刃隐遥克服了诸多困难，终于在魂器学院中和自己的“姐姐大人”相遇时，才发现她已经和以前不一样了。</p>",
		name = "【刃隐一族】",
		story1 = 20210158
	},
	[20210159] = {
		dec = "<p>&nbsp; &nbsp;枫，月，泉三人是月和会当中相当知名的组合，三人的出身相似，却有着截然不同的性格。生性外向，喜欢横冲直撞的枫；沉着冷静，身为小队的领队，要负责打点他人生活的月；生性胆小，一直觉得自己在给另外两人拖后腿，而有些内疚的泉。她们身为芙蕾影子护卫，对芙蕾有着相当程度的尊敬与忠诚，单论协调作战能力，她们在整个学院当中也是首屈一指的。</p>",
		name = "【枫月泉】",
		story1 = 20210159
	},
	[20210160] = {
		dec = "<p>&nbsp; &nbsp;水原雾夜作为水原家族本家的独女，自小便受到了家族中所有人的关注，被誉为水原家的天才。直到水原家族旁系当中水原堇的出现。水原堇在各方面的天赋都要略胜水原雾夜一筹，而在某一次模拟战上，水原堇轻松击败了水原雾夜，震惊了整个家族。从水原雾夜的角度来看，水原堇就像是突然出现，抢走自己风光的坏孩子，因此对她产生了对抗心理。至于水原堇，在战胜水原雾夜之后，很多旁系家族的人都想要借此推翻旁系与本家之间的绝对地位关系，但水原堇对此却没有任何兴趣，她只要能研究自己钟爱的帅气招式就很满足了。就这样，水原家族本家和旁系的关系回归了一触即发却又相对平稳的状态。</p>",
		name = "【本家与旁系】",
		story1 = 20210160
	},
	[20210161] = {
		dec = "<p>&nbsp; &nbsp;洛可可与天瞳都是精神年龄远远大于外表年龄的人，一方是因为被奇怪的射线影响，变得不会衰老，在现实世界渡过了200年的岁月；一方是被置入培养仓，以百倍的流速体验了数百年的岁月。不过，同为“老人”，洛可可在处理人际关系方面的水平就比天瞳强得多了，一手组建起整个托拉组织的洛可可正可谓是天瞳的楷模，天瞳也在班长的引荐下，向洛可可请教起了“获得年长者的威严”的方法。</p>",
		name = "【萝莉老太婆】",
		story1 = 20210161
	},
	[20210162] = {
		dec = "<p>&nbsp; &nbsp;阿芙洛和尤利娅都很擅长伪装自己，但这两人却是难以相容的存在。阿芙洛并不喜欢在任务之外的场合装点自己，因为她对于自我的容貌有着过度的重视。而尤利娅则将变装视为一种兴趣，以体验不同的外表，不同人的人生为乐。阿芙洛和尤利娅都表示过，自己看不惯对方那样的人，两人的关系虽然也很紧张，但好在目前为止还没有发生过冲突。</p>",
		name = "【相似而不相容】",
		story1 = 20210162
	}
}
